'use strict';
/**
 * Amboss 200 Concepts — HY explanations, one per question, keyed by the
 * question's business key (AMB200-001 … AMB200-200).
 *
 * Original teaching text written for this app (the questions themselves stay
 * out of the public repo — see tools/amboss-200). Written to be read quickly
 * by a student: full sentences, plain words, abbreviations spelled out, no
 * arrow shorthand. Each entry:
 *   c   the concept in a few words (the card's headline)
 *   w   why the answer is right, in two or three plain sentences
 *   hy  the key points that go with it, each a full sentence; a short
 *       "Label: " at the start is shown in bold by the card
 *   t   optional: the common trap — the answer people pick and why it is wrong
 *
 * The /api/amboss200/run endpoint attaches the entry as `hy` on each question.
 */

const HY = {};
const add = (obj) => Object.assign(HY, obj);

// ── Biochemistry and genetics ───────────────────────────────────────────────
add({
  'AMB200-001': { c: 'Red–green color blindness is X-linked recessive',
    w: 'Only boys are affected, and the condition is passed from carrier mothers to their sons. It is never passed from father to son. That is the classic pattern of an X-linked recessive disease.',
    hy: ['Pattern: affected males, healthy carrier females, and no father-to-son transmission.', 'Children of a carrier mother: each son has a 50% chance of being affected, and each daughter has a 50% chance of being a carrier.', 'Other X-linked recessive diseases: hemophilia A and B, Duchenne muscular dystrophy, G6PD deficiency, Fabry disease, Lesch–Nyhan syndrome, Bruton agammaglobulinemia and Wiskott–Aldrich syndrome.'],
    t: 'X-linked dominant diseases also have no father-to-son spread, but there an affected father passes the disease to every one of his daughters.' },
  'AMB200-002': { c: 'Pleiotropy: one gene, many effects',
    w: 'In phenylketonuria (PKU), one faulty gene for phenylalanine hydroxylase causes many different problems at once. The child has intellectual disability, seizures, fair skin and blue eyes, and a musty smell. One gene causing many unrelated traits is called pleiotropy.',
    hy: ['Cause: phenylalanine hydroxylase or its cofactor BH4 is missing, so phenylalanine builds up and tyrosine has to come from the diet.', 'Signs: a musty or mousy body odor, fair hair and skin because less melanin is made, eczema and intellectual disability.', 'Maternal PKU: a mother with poorly controlled PKU can have a baby with microcephaly and heart defects, so she needs a low-phenylalanine diet in pregnancy.'],
    t: 'Variable expressivity means the same gene causes mild disease in one person and severe disease in another (for example NF1). It does not mean many traits in one person.' },
  'AMB200-003': { c: 'Prader–Willi syndrome: loss of the father’s copy of 15q11–13',
    w: 'In this region of chromosome 15, the mother’s copy is normally switched off (imprinted). The child relies only on the father’s copy. If the father’s copy is deleted, or if both copies come from the mother (uniparental disomy), no working gene is left.',
    hy: ['Prader–Willi: constant hunger with obesity, floppy muscles in infancy, small genitals, intellectual disability and almond-shaped eyes.', 'Angelman syndrome: loss of the mother’s UBE3A gene, causing a happy, puppet-like manner, seizures, poor balance and laughter at odd times.', 'About 25% of Prader–Willi cases are caused by maternal uniparental disomy rather than a deletion.'] },
  'AMB200-004': { c: 'Fragile X syndrome (CGG repeat in FMR1)',
    w: 'The boy has a long face, large protruding ears, a large jaw and very large testes. He also has intellectual disability with attention and autism-like features. This combination is fragile X syndrome.',
    hy: ['Cause: an expanded CGG repeat in the FMR1 gene leads to methylation, which switches the gene off. It is X-linked and gets worse in later generations when passed through the mother.', 'It is the most common inherited cause of intellectual disability. Down syndrome is the most common genetic cause overall.', 'Other features: mitral valve prolapse and very flexible joints.'],
    t: 'Frontal balding with cataracts points to myotonic dystrophy, which is a CTG repeat disease.' },
  'AMB200-005': { c: 'Primary ciliary dyskinesia (Kartagener syndrome)',
    w: 'The cilia cannot beat, so mucus is not cleared from the sinuses and airways and sperm cannot swim. This causes chronic sinusitis, bronchiectasis and male infertility. About half of patients also have their organs reversed (situs inversus).',
    hy: ['Cause: an autosomal recessive defect in dynein, the motor protein of the cilia.', 'Screening clue: nitric oxide measured in the nose is low.', 'In women: the cilia of the fallopian tubes do not work, so ectopic pregnancy and reduced fertility are more common.'],
    t: 'Cystic fibrosis also causes sinusitis, bronchiectasis and male infertility, but the cilia are normal. Men with CF are infertile because the vas deferens is missing.' },
  'AMB200-006': { c: 'Edwards syndrome (trisomy 18)',
    w: 'Clenched fists with overlapping fingers, rocker-bottom feet, a prominent back of the head, a small jaw, low-set ears and a heart murmur from a ventricular septal defect are the signs of trisomy 18.',
    hy: ['Most babies die within the first year. The risk rises with the mother’s age because of nondisjunction during meiosis.', 'Quad screen: AFP, beta-hCG and estriol are all low, and inhibin is normal.', 'Trisomy 13 (Patau syndrome) is different: cleft lip and palate, holoprosencephaly, extra fingers and missing patches of scalp skin.'] },
  'AMB200-007': { c: 'Wernicke encephalopathy brought on by glucose',
    w: 'This patient had very little thiamine left. Giving glucose made the body burn through the last of it, because thiamine is needed to break glucose down. This triggered confusion, eye movement problems and an unsteady gait.',
    hy: ['Thiamine (vitamin B1) is a cofactor for pyruvate dehydrogenase, alpha-ketoglutarate dehydrogenase, branched-chain ketoacid dehydrogenase and transketolase.', 'Test: red blood cell transketolase activity is low and rises when thiamine is added.', 'Always give thiamine before glucose to malnourished patients or people with alcohol use disorder. The mammillary bodies are the part of the brain that is damaged.'] },
  'AMB200-008': { c: 'Pompe disease (acid maltase deficiency)',
    w: 'An infant with a large heart, a large tongue, floppy muscles and a normal blood sugar has Pompe disease. It is the glycogen storage disease that mainly damages the heart.',
    hy: ['Memory aid: “Pompe trashes the pump.” Heart, liver and muscle are affected, and death from heart failure often comes early.', 'Glycogen builds up inside lysosomes. Blood sugar stays normal because the main pathway for releasing glucose still works.', 'Compare with von Gierke disease (glucose-6-phosphatase deficiency): severe low blood sugar when fasting, lactic acidosis and a large liver.'] },
  'AMB200-009': { c: 'Carcinoid syndrome: block serotonin production with telotristat',
    w: 'Tryptophan hydroxylase is the first and slowest step in making serotonin from tryptophan. Telotristat blocks this enzyme, so the tumor makes less serotonin. This helps carcinoid diarrhea that octreotide has not controlled.',
    hy: ['Carcinoid syndrome usually appears only once the tumor has spread to the liver, because the liver normally breaks serotonin down before it reaches the body.', 'Signs: flushing, diarrhea, wheezing and right-sided heart valve disease. Urine 5-HIAA is raised.', 'The tumor uses up tryptophan, so the body cannot make enough niacin, which can cause pellagra.'] },
  'AMB200-010': { c: 'Fluoroquinolones block DNA gyrase (topoisomerase II)',
    w: 'As DNA is unwound for copying, it twists into tight supercoils ahead of the replication fork. Topoisomerases cut the DNA to release that tension. Fluoroquinolones block the bacterial topoisomerases II (gyrase) and IV, so the bacteria cannot copy their DNA.',
    hy: ['Replication steps: helicase unwinds the DNA, single-strand binding proteins keep the strands apart, primase lays down a primer and DNA polymerase III builds the new strand.', 'DNA polymerase I removes the RNA primer and fills the gap, and DNA ligase joins the short Okazaki fragments together.', 'Fluoroquinolone side effects: tendon rupture, a long QT interval and cartilage damage in children.'] },
  'AMB200-011': { c: 'Gaucher disease (glucocerebrosidase deficiency)',
    w: 'A large liver and spleen, low blood counts, bone pain with damaged bones and macrophages that look like crumpled tissue paper are the signs of Gaucher disease.',
    hy: ['It is the most common lysosomal storage disease. It is autosomal recessive and more common in Ashkenazi Jewish people.', 'Treatment: replace the missing enzyme with recombinant glucocerebrosidase (imiglucerase).', 'Niemann–Pick disease is different: sphingomyelinase deficiency causes a large liver and spleen, loss of brain function, a cherry-red spot on the retina and foamy macrophages.'] },
  'AMB200-012': { c: 'Ehlers–Danlos syndrome: faulty collagen cross-linking',
    w: 'Very stretchy, fragile skin, easy bruising and very flexible joints happen when collagen fibers are not built or linked together properly. The problem is at the final cross-linking step.',
    hy: ['How collagen is made: vitamin C helps add hydroxyl groups, three chains wind into a triple helix, the molecule is released from the cell and trimmed, and lysyl oxidase (which needs copper) links the molecules together.', 'Classic Ehlers–Danlos involves type V collagen. The vascular type involves type III collagen and can rupture arteries or the uterus.', 'Menkes disease: low copper means lysyl oxidase cannot work, causing brittle, kinky hair.'],
    t: 'Faulty hydroxylation is scurvy, and a faulty triple helix is osteogenesis imperfecta.' },
  'AMB200-013': { c: 'Insulin is a building-up (anabolic) hormone',
    w: 'Insulin tells the body to store fuel. It increases glucose breakdown and glycogen storage, and it switches off fat breakdown and the making of new glucose.',
    hy: ['Insulin increases fructose-2,6-bisphosphate, which speeds up glycolysis, and it switches glycogen synthase on.', 'It blocks hormone-sensitive lipase so fat is not broken down, and it moves potassium into cells.', 'Glargine is a long-acting background insulin with a flat effect and no peak.'] },
  'AMB200-014': { c: 'Vitamin B12 deficiency (methylmalonyl-CoA mutase)',
    w: 'A strict vegan has large-cell anemia and loss of position and vibration sense. Vegans can run out of vitamin B12. B12 is needed by two enzymes: methylmalonyl-CoA mutase and methionine synthase.',
    hy: ['Blood tests: in B12 deficiency both methylmalonic acid and homocysteine are high. In folate deficiency only homocysteine is high.', 'Nerve damage (subacute combined degeneration) affects the dorsal columns, the lateral corticospinal tracts and the spinocerebellar tracts.', 'Giving folate alone fixes the anemia but does not stop the nerve damage.'] },
  'AMB200-015': { c: 'Vitamin D deficiency from poor fat absorption in cystic fibrosis',
    w: 'In cystic fibrosis the pancreas does not release enough enzymes, so fat and fat-soluble vitamins are poorly absorbed. Low vitamin D lowers calcium and phosphate, and the parathyroid glands respond by making more PTH. In a child this causes rickets.',
    hy: ['Rickets: wide growth plates, bowed legs, bead-like swellings along the ribs and a soft skull.', 'Vitamins A, D, E and K are all lost in cystic fibrosis, celiac disease and bile duct disease.', 'The extra PTH brings calcium back up, but it makes the kidneys lose phosphate.'] },
  'AMB200-016': { c: 'Transaminases need vitamin B6 (pyridoxal phosphate)',
    w: 'The liver enzymes AST and ALT move amino groups from one molecule to another. They can only do this with vitamin B6, in the form of pyridoxal phosphate, as their helper.',
    hy: ['Vitamin B6 is also needed to make heme (ALA synthase), to release glucose from glycogen, to make cystathionine and to make neurotransmitters.', 'Isoniazid uses up B6 and can cause nerve damage, sideroblastic anemia and seizures.', 'Methotrexate can damage the liver, so liver tests are checked regularly.'] },
});

// ── General pathology ───────────────────────────────────────────────────────
add({
  'AMB200-017': { c: 'Apoptosis through the intrinsic (mitochondrial) pathway',
    w: 'The cells shrink, turn pink, have small dense nuclei and bulge at the membrane, but there is no inflammation. This is apoptosis, programmed cell death. Here it was triggered because the cells lost the nerve supply that kept them alive, which releases cytochrome c from the mitochondria.',
    hy: ['Intrinsic pathway: the survival protein Bcl-2 falls, BAX and BAK make holes in the mitochondria, cytochrome c leaks out and caspase-9 is switched on.', 'Extrinsic pathway: a signal from outside the cell, such as Fas ligand or TNF, switches on caspase-8.', 'Both pathways end by switching on the executioner caspases 3, 6 and 7.'] },
  'AMB200-018': { c: 'Splenic infarct: coagulative necrosis',
    w: 'When a solid organ such as the spleen loses its blood supply, the tissue dies by coagulative necrosis. The outline of the tissue is kept, but the cells look like pale ghosts with no nuclei. The brain is the exception.',
    hy: ['Brain infarcts cause liquefactive necrosis, where the tissue turns soft and liquid.', 'Pale infarcts happen in solid organs with one blood supply (heart, kidney, spleen). Red, bloody infarcts happen in loose tissue or tissue with two blood supplies (lung, liver, bowel, testis).', 'In atrial fibrillation, a clot can form in the atrium and travel to the brain, kidney or spleen.'] },
  'AMB200-019': { c: 'Methemoglobinemia',
    w: 'Dapsone changes the iron in hemoglobin from the ferrous (Fe2+) form to the ferric (Fe3+) form, which cannot carry oxygen. The oxygen dissolved in the blood (PaO2) and the hemoglobin level are normal, but oxygen saturation and oxygen content fall. The blood looks chocolate brown.',
    hy: ['Causes: dapsone, nitrates and nitrites, local anesthetics such as benzocaine, and sulfonamides.', 'Pulse oximetry tends to read about 85% no matter what the true saturation is.', 'Treatment: methylene blue, with vitamin C as an option. Avoid methylene blue in G6PD deficiency.'] },
  'AMB200-020': { c: 'Neutrophils are called in by leukotriene B4',
    w: 'In smokers, elastase released by neutrophils destroys the walls of the air sacs and causes emphysema. Neutrophils are drawn into the lung by chemical signals, and leukotriene B4 is one of the strongest.',
    hy: ['Signals that attract neutrophils: C5a, IL-8, leukotriene B4, 5-HETE, kallikrein and platelet-activating factor.', 'Alpha-1 antitrypsin deficiency damages the lower parts of the lungs (panacinar). Smoking damages the upper parts (centriacinar).', 'Emphysema happens when there is too much elastase and too little of the proteins that block it.'] },
  'AMB200-021': { c: 'Wound contraction is done by myofibroblasts',
    w: 'Myofibroblasts are fibroblasts that contain muscle-type proteins, so they can pull the edges of a wound together. If they pull too hard, the scar tightens into a contracture.',
    hy: ['Healing has three phases: inflammation (days 0 to 3), new tissue growth (from day 3 for a few weeks, with type III collagen) and remodeling (type III collagen is replaced by stronger type I).', 'A hypertrophic scar stays within the wound edges. A keloid grows beyond them.', 'Zinc and vitamin C are both needed for normal healing.'] },
  'AMB200-022': { c: 'Swelling in inflammation comes from gaps between endothelial cells',
    w: 'Histamine and other inflammatory chemicals make the endothelial cells of small venules contract. Gaps open between them, and fluid rich in protein leaks out into the tissue.',
    hy: ['Fluid from inflammation (exudate) is high in protein. Fluid from high pressure or low protein in the blood (transudate) is low in protein.', 'Redness and warmth come from widened arterioles. Swelling comes from leaky vessels.', 'An abscess is a soft, fluid-filled collection of neutrophils, often caused by Staphylococcus aureus.'] },
  'AMB200-023': { c: 'Granulomas are made of epithelioid macrophages',
    w: 'The granulomas of tuberculosis are made of activated macrophages, called epithelioid cells, and large multinucleated giant cells, with a ring of lymphocytes around them.',
    hy: ['Th1 cells release interferon-gamma, which activates the macrophages. The macrophages then release TNF-alpha, which keeps the granuloma together.', 'Drugs that block TNF can wake up latent tuberculosis, so patients are tested for TB before starting them.', 'Granulomas without central necrosis (noncaseating) are seen in sarcoidosis, Crohn disease and berylliosis.'] },
  'AMB200-024': { c: 'Aldesleukin (IL-2) activates NK cells and cytotoxic T cells',
    w: 'Aldesleukin is a man-made form of interleukin-2. It makes cytotoxic T cells and natural killer cells multiply so they attack the cancer. It is used for metastatic melanoma and kidney cancer.',
    hy: ['Main side effect: capillary leak syndrome, where fluid leaks out of the blood vessels.', 'Melanoma markers: S-100 and HMB-45. Tumors with the BRAF V600E mutation can be treated with vemurafenib.', 'Checkpoint inhibitors such as ipilimumab (CTLA-4) and nivolumab (PD-1) are now the first choice.'] },
  'AMB200-025': { c: 'Stage matters more than grade',
    w: 'How far a cancer has spread (its stage) predicts the outcome better than how abnormal the cells look (its grade). This tumor has grown into the mediastinum, so it is advanced, whatever its cells look like.',
    hy: ['Grade describes how abnormal the cells look under the microscope and how fast they are dividing.', 'Stage describes the tumor size, lymph node spread and distant spread (TNM). It is the most important factor for prognosis.', 'Squamous cell lung cancer: central, can cavitate, linked to smoking, can raise calcium through PTHrP and shows keratin pearls.'] },
  'AMB200-026': { c: 'Lynch syndrome: microsatellite instability',
    w: 'MLH1 is one of the genes that fix copying mistakes in DNA (mismatch repair). When it fails, errors pile up in short repeated stretches of DNA called microsatellites. This leads to colon, endometrial and ovarian cancer.',
    hy: ['Lynch syndrome (HNPCC) is autosomal dominant. It often causes right-sided colon cancer before age 50.', 'The mismatch repair genes are MLH1, MSH2, MSH6 and PMS2.', 'A defect in nucleotide excision repair, which fixes damage from UV light, causes xeroderma pigmentosum instead.'] },
  'AMB200-027': { c: 'Li–Fraumeni syndrome: inherited TP53 mutation',
    w: 'Several young family members have sarcoma, breast cancer, adrenal cancer and brain tumors. This mix of cancers at young ages points to Li–Fraumeni syndrome.',
    hy: ['The p53 protein stops a damaged cell before it copies its DNA, giving time for repair or programmed cell death.', 'It is autosomal dominant. One faulty copy is inherited and the second is lost later in life (the two-hit idea).', 'Other cancer genes: RB causes retinoblastoma and osteosarcoma, RET causes MEN2 and PTEN causes Cowden syndrome.'] },
  'AMB200-028': { c: 'Brain metastases most often come from the lung',
    w: 'Several round, well-defined lesions where the gray matter meets the white matter are metastases. In adults the lung is the most common source.',
    hy: ['Most common sources, in order: lung, breast, melanoma, kidney and bowel.', 'In adults, metastases to the brain are more common than tumors that start in the brain.', 'Melanoma metastases often bleed.'] },
  'AMB200-029': { c: 'Bone-forming (blastic) metastases come from the prostate',
    w: 'An older man has spinal cord compression and dense, bone-forming lesions in the spine. This pattern points to prostate cancer, and his PSA will be raised.',
    hy: ['Bone-forming lesions: prostate (and small cell lung cancer). Bone-destroying lesions: myeloma, kidney, thyroid and melanoma. Mixed lesions: breast.', 'Prostate cancer reaches the spine through a network of veins called the Batson plexus.', 'Cancer that has spread to bone is much more common than cancer that starts in bone.'] },
});

// ── General pharmacology ────────────────────────────────────────────────────
add({
  'AMB200-030': { c: 'Urge incontinence is treated with antimuscarinics',
    w: 'In urge incontinence the bladder muscle (detrusor) contracts when it should not. These contractions are driven by M3 muscarinic receptors. Oxybutynin, tolterodine and solifenacin block those receptors and relax the bladder.',
    hy: ['Another option is mirabegron, a beta-3 agonist, which also relaxes the bladder muscle.', 'Stress incontinence is treated differently, with pelvic floor exercises or surgery.', 'Antimuscarinic side effects: dry mouth, constipation and confusion in older people.'] },
  'AMB200-031': { c: 'Desmopressin acts on V2 receptors and raises cAMP',
    w: 'Desmopressin binds V2 receptors on the collecting duct cells. This raises cAMP, which puts aquaporin-2 water channels into the cell membrane. More water is taken back into the blood, so less urine is made at night.',
    hy: ['V1 receptors tighten blood vessels. V2 receptors control water reabsorption in the kidney.', 'Desmopressin also treats central diabetes insipidus, hemophilia A and von Willebrand disease, because it releases von Willebrand factor.', 'Main risk: low blood sodium.'] },
  'AMB200-032': { c: 'Competitive antagonist: the curve shifts right but the maximum stays the same',
    w: 'A competitive antagonist competes with the drug for the same site. You need more of the drug to get the same effect, so the curve shifts to the right (lower potency). With enough drug you still reach the same maximum effect.',
    hy: ['Noncompetitive antagonist: lowers the maximum effect (lower efficacy), and the potency does not change.', 'Partial agonist: gives a smaller maximum effect than a full agonist, even when every receptor is occupied.', 'For enzymes, a competitive inhibitor raises Km but leaves Vmax the same.'] },
  'AMB200-033': { c: 'Vmax rises when there is more enzyme',
    w: 'Vmax doubled while Km stayed the same. This means there is simply more enzyme present. Km reflects how strongly the enzyme binds its substrate, and that does not change with the amount of enzyme.',
    hy: ['Competitive inhibitor: Km goes up and Vmax stays the same.', 'Noncompetitive inhibitor: Vmax goes down and Km stays the same.', 'Km is the substrate level at which the enzyme works at half its maximum speed. A lower Km means the enzyme binds more strongly.'] },
  'AMB200-034': { c: 'Bioavailability is close to 100% when the oral and IV areas under the curve match',
    w: 'Once corrected for dose, the area under the curve after an oral dose is the same as after an IV dose. That means nearly all of the swallowed drug reaches the blood, as with isosorbide mononitrate.',
    hy: ['Bioavailability equals the oral area under the curve divided by the IV area under the curve.', 'Isosorbide mononitrate is not broken down by the liver on its first pass. Nitroglycerin and isosorbide dinitrate are.', 'Nitrates release nitric oxide, which raises cGMP and relaxes the veins. This lowers the amount of blood returning to the heart (preload).'] },
  'AMB200-035': { c: 'Clinical trial phases',
    w: 'The answer key gives Phase II. However, a small study that looks for the highest safe dose and for side effects is usually described as Phase I, so check this one against your source.',
    hy: ['Phase I: a small number of healthy volunteers. It tests safety, side effects, how the body handles the drug and the highest safe dose.', 'Phase II: a small number of patients who have the disease. It tests whether the drug works, the best dose and side effects.', 'Phase III: a large randomized trial against the standard treatment. Phase IV: monitoring after the drug is on the market.'] },
  'AMB200-036': { c: 'Griseofulvin speeds up liver enzymes, so warfarin stops working',
    w: 'Griseofulvin, started for a fungal nail infection, induces the liver’s cytochrome P450 enzymes. Warfarin is then broken down faster, so her INR fell to 1.5. With too little anticoagulation she had a stroke from a clot.',
    hy: ['Drugs that speed up P450: carbamazepine, rifampin, phenytoin, griseofulvin, St John’s wort, long-term alcohol use and phenobarbital.', 'Drugs that slow P450: macrolides, azole antifungals, grapefruit juice, cimetidine, ritonavir, binge drinking and amiodarone.', 'Target INR on warfarin for atrial fibrillation: 2 to 3.'] },
});

// ── Microbiology ────────────────────────────────────────────────────────────
add({
  'AMB200-037': { c: 'Chronic granulomatous disease: infections with catalase-positive organisms',
    w: 'An abnormal dihydrorhodamine test means NADPH oxidase is missing. Without it, white cells cannot make the toxic oxygen they use to kill germs. Organisms that make catalase destroy their own hydrogen peroxide, so they survive.',
    hy: ['Typical organisms: Staphylococcus aureus, Serratia, Nocardia, Burkholderia cepacia, Aspergillus and Candida.', 'Most cases are X-linked. The nitroblue tetrazolium test is also abnormal.', 'Prevention: daily TMP-SMX and itraconazole, sometimes with interferon-gamma.'] },
  'AMB200-038': { c: 'Streptococcus pneumoniae: the capsule is its main weapon',
    w: 'Lancet-shaped pairs of cocci that partly break down blood (alpha-hemolytic, turning the agar green) and cause lobar pneumonia are pneumococcus. Its most important virulence factor is its sugar capsule, which stops white cells from eating it.',
    hy: ['Lab tests: sensitive to optochin, dissolves in bile and shows a positive quellung reaction.', 'It is the most common cause of community-acquired pneumonia, meningitis and middle ear infection in adults.', 'People without a working spleen are at high risk and should be vaccinated.'] },
  'AMB200-039': { c: 'Klebsiella pneumonia: lipid A causes shock',
    w: 'Gram-negative rods with a capsule, in a man with diabetes and alcohol use disorder who coughs up red currant-jelly sputum, are Klebsiella. Lipid A, part of the bacterial endotoxin, makes immune cells release cytokines that drop the blood pressure.',
    hy: ['Lipid A binds TLR4 on macrophages, which release IL-1, TNF-alpha and IL-6. These cause fever, septic shock and abnormal clotting.', 'Klebsiella causes aspiration pneumonia in people who drink heavily, lung abscesses and urinary infections. It ferments lactose and looks mucoid.', 'Neisseria has a similar molecule called lipooligosaccharide.'] },
  'AMB200-040': { c: 'Pertussis toxin raises cAMP',
    w: 'Pertussis toxin switches off the inhibitory G protein (Gi). Adenylate cyclase is then left on all the time, so cAMP rises. A very high lymphocyte count is typical.',
    hy: ['Stages: a cold-like phase, then bouts of coughing with a whoop and vomiting after coughing, then slow recovery.', 'Treatment is a macrolide. Prevention is vaccination, including a Tdap booster in every pregnancy.', 'Other toxins that raise cAMP: cholera toxin, heat-labile E. coli toxin and anthrax edema factor.'] },
  'AMB200-041': { c: 'Mycoplasma pneumoniae: cold agglutinins',
    w: 'A young adult living in barracks has a mild walking pneumonia. He also has blue fingertips in the cold, mild hemolytic anemia and target-shaped skin lesions. Mycoplasma triggers IgM antibodies that clump red cells in the cold (cold agglutinins).',
    hy: ['Mycoplasma has no cell wall, so penicillins and cephalosporins do not work. Use a macrolide, doxycycline or a fluoroquinolone.', 'Its membrane contains cholesterol, and it grows on Eaton agar.', 'The chest X-ray often looks worse than the patient.'],
    t: 'Coccidioides, found in southern California, causes tender red nodules on the shins (erythema nodosum) and joint pain, not cold-agglutinin hemolysis.' },
  'AMB200-042': { c: 'Bacillus cereus from reheated rice',
    w: 'Vomiting that starts 1 to 6 hours after eating reheated rice is the vomiting form of Bacillus cereus. It is caused by a toxin, cereulide, that is already in the food and is not destroyed by heat.',
    hy: ['Vomiting form: toxin already in the food, symptoms within 1 to 6 hours. Diarrhea form: toxin made in the gut, symptoms after 8 to 18 hours.', 'Staphylococcus aureus also has a ready-made toxin, causing vomiting 2 to 6 hours after mayonnaise, custard or meat.', 'The spores survive cooking and grow when cooked rice is kept warm.'] },
  'AMB200-043': { c: 'Primary syphilis is treated with penicillin G',
    w: 'A painless, firm genital ulcer with spirochetes seen on dark-field microscopy is primary syphilis. Penicillin blocks the bacterial transpeptidase enzyme, so the bacteria cannot build their cell wall.',
    hy: ['First choice: one injection of benzathine penicillin G into the muscle. Doxycycline is used for penicillin allergy, but not in pregnancy.', 'A few hours after treatment the patient may get fever and muscle aches as the spirochetes die (Jarisch–Herxheimer reaction).', 'Testing: screen with VDRL or RPR, then confirm with a specific test such as FTA-ABS.'] },
  'AMB200-044': { c: 'Porphyria cutanea tarda caused by hepatitis C',
    w: 'Blisters on sun-exposed hands plus chronic liver disease point to porphyria cutanea tarda, triggered here by hepatitis C. Hepatitis C spreads through blood, for example through needlestick injuries or shared needles.',
    hy: ['Porphyria cutanea tarda is caused by low uroporphyrinogen decarboxylase. The urine may be tea-colored.', 'Hepatitis C can also cause problems outside the liver: mixed cryoglobulinemia, membranoproliferative glomerulonephritis and lichen planus.', 'Hepatitis C is treated with direct-acting antivirals such as sofosbuvir.'] },
  'AMB200-045': { c: 'CCR5 lets HIV enter macrophages',
    w: 'The strain of HIV that infects macrophages needs two receptors: CD4 and CCR5. A mutation in CCR5 slows or blocks infection. People with two faulty copies are resistant.',
    hy: ['The strain that infects T cells uses CXCR4 instead. The viral protein gp120 binds CD4, and gp41 lets the virus fuse with the cell.', 'The drug maraviroc blocks CCR5.', 'Pneumocystis pneumonia: beta-D-glucan is raised, both lungs show diffuse changes and the CD4 count is below 200.'] },
  'AMB200-046': { c: 'HIV: preventive antibiotics depend on the CD4 count',
    w: 'When the CD4 count falls below 200, start TMP-SMX to prevent Pneumocystis pneumonia.',
    hy: ['CD4 below 200: start TMP-SMX to prevent Pneumocystis.', 'CD4 below 100 with a positive Toxoplasma antibody test: TMP-SMX also protects against toxoplasmosis.', 'MAC prevention with azithromycin at CD4 below 50 is no longer routine if antiretroviral therapy is started.'] },
  'AMB200-047': { c: 'Zidovudine stops the viral DNA chain from growing',
    w: 'Nucleoside reverse transcriptase inhibitors (NRTIs) look like the normal DNA building blocks but lack the 3-prime OH group. Once one is added, no further building block can attach, so the viral DNA chain stops growing.',
    hy: ['NRTIs must be phosphorylated inside the cell to work. NNRTIs do not need this.', 'Zidovudine side effect: bone marrow suppression with large red cells.', 'IV zidovudine during labor lowers the chance of passing HIV to the baby.'] },
  'AMB200-048': { c: 'Entamoeba histolytica: bloody diarrhea',
    w: 'Stool microscopy shows amoebae that have swallowed red blood cells, and the patient has bloody, mucus-filled diarrhea after travel. This is amebic dysentery.',
    hy: ['It makes flask-shaped ulcers in the colon and can cause a liver abscess with fluid that looks like anchovy paste.', 'Treatment: metronidazole, followed by iodoquinol or paromomycin to clear the cysts left in the gut.', 'It spreads through cysts in food or water contaminated by feces.'] },
  'AMB200-049': { c: 'Plasmodium falciparum: resistant to chloroquine',
    w: 'Irregular fevers, red cell breakdown and a large spleen, with ring forms and banana-shaped gametocytes on the blood smear, despite chloroquine prophylaxis, mean falciparum malaria.',
    hy: ['Falciparum is the most dangerous species. It can cause cerebral malaria, kidney failure with dark urine and fluid in the lungs.', 'Chloroquine resistance is widespread, so use artemisinin drugs, atovaquone-proguanil or mefloquine.', 'Vivax and ovale hide in the liver as hypnozoites, so primaquine is added. Check for G6PD deficiency first.'] },
  'AMB200-050': { c: 'Cryptococcus: a capsule that stains red with mucicarmine',
    w: 'Budding yeast with a thick capsule that stains red with mucicarmine (or shows a clear halo with India ink in spinal fluid) is Cryptococcus neoformans.',
    hy: ['It lives in pigeon droppings and causes meningitis when the CD4 count is below 100.', 'A latex agglutination test detects its capsule in blood or spinal fluid.', 'Treatment: amphotericin B with flucytosine, then fluconazole.'] },
  'AMB200-051': { c: 'Trichomonas vaginalis',
    w: 'A frothy, green-yellow, bad-smelling discharge with itching and tiny red spots on the cervix (strawberry cervix), with moving flagellated organisms on the slide, is trichomoniasis.',
    hy: ['A wet mount shows moving, pear-shaped organisms, and the vaginal pH is above 4.5.', 'Treat both the patient and the partner with metronidazole.', 'Bacterial vaginosis has a thin gray fishy discharge and clue cells without inflammation. Candida has a thick, cottage-cheese discharge with normal pH.'] },
});

// ── Immune system ───────────────────────────────────────────────────────────
add({
  'AMB200-052': { c: 'The immune system weakens with age (immunosenescence)',
    w: 'As we age, the thymus shrinks and fewer new (naive) T cells and B cells are made. Older people therefore respond less well to new infections and to vaccines.',
    hy: ['In older people: fewer naive T cells, antibodies that bind less strongly, more autoantibodies, and more infections and cancers.', 'High-dose or boosted flu vaccines are used in older adults for this reason.', 'The number of neutrophils stays roughly normal.'] },
  'AMB200-053': { c: 'Chronic mucocutaneous candidiasis: a T-cell defect',
    w: 'Repeated Candida infections of the mouth and nails mean the T cells, especially Th17 cells, are not working. B cells and complement do not control Candida on the skin and mucosa.',
    hy: ['T-cell defects lead to infections with fungi, viruses, organisms that live inside cells, and Candida of the skin and mucosa.', 'Neutrophil defects lead to deep (invasive) Candida and Aspergillus infections and to catalase-positive bacteria.', 'Defects in Th17 cells or IL-17, such as AIRE or STAT3 mutations, cause mucocutaneous candidiasis.'] },
  'AMB200-054': { c: 'Goodpasture syndrome is a type II hypersensitivity',
    w: 'Antibodies attack type IV collagen in the basement membranes of the lung air sacs and the kidney glomeruli. An antibody binding to a fixed target in the body is a type II reaction, the same type as autoimmune hemolytic anemia.',
    hy: ['Immunofluorescence shows a smooth, linear line of IgG. Patients cough up blood and have blood in the urine from rapidly progressive glomerulonephritis.', 'The target is the alpha-3 chain of type IV collagen. Treatment is plasmapheresis, steroids and cyclophosphamide.', 'Type III reactions are different: immune complexes deposit in tissues, as in post-strep glomerulonephritis, polyarteritis nodosa, lupus and serum sickness.'] },
  'AMB200-055': { c: 'Acute cellular rejection',
    w: 'Rejection a few days to weeks after a transplant, with T cells inside the kidney tubules and a negative C4d stain, is T-cell mediated. The patient’s own T cells recognize the donor’s MHC molecules as foreign.',
    hy: ['Hyperacute rejection (within minutes): antibodies already present against the donor blood group or HLA cause the graft vessels to clot.', 'Acute antibody-mediated rejection is C4d positive. Chronic rejection scars the graft vessels over months to years.', 'Graft-versus-host disease is the reverse: the donor’s T cells attack the patient, usually after bone marrow or liver transplant.'] },
  'AMB200-056': { c: 'Tetanus is prevented with a toxoid vaccine',
    w: 'An unvaccinated child with lockjaw, an arched back and muscle spasms after a dirty wound has tetanus. It is prevented with a toxoid vaccine, which is the toxin made harmless with formaldehyde.',
    hy: ['Tetanus toxin stops Renshaw cells releasing the calming transmitters GABA and glycine, so the muscles cannot relax.', 'Toxoid vaccines: tetanus and diphtheria. The pertussis vaccine is made of bacterial proteins.', 'Treatment: tetanus immune globulin, a toxoid dose, metronidazole and benzodiazepines.'] },
  'AMB200-057': { c: 'Leukocyte adhesion deficiency type 1 (CD18)',
    w: 'Late falling-off of the umbilical cord, a very high neutrophil count and infections that make no pus are the signs of leukocyte adhesion deficiency type 1. The integrin CD18 is missing, so neutrophils cannot stick to the vessel wall and leave the blood.',
    hy: ['It is autosomal recessive. Neutrophils cannot hold firmly to the vessel wall or squeeze through it.', 'Other signs: no pus, poor wound healing and gum disease.', 'Chédiak–Higashi syndrome is different: a defect in moving material inside cells causes giant granules and pale skin and hair.'] },
  'AMB200-058': { c: 'Lack of the final complement proteins (C5 to C9) leads to Neisseria infections',
    w: 'Without C5 to C9, the body cannot build the membrane attack complex that punches holes in bacteria. Patients get repeated meningococcal and gonococcal infections.',
    hy: ['Lack of the early complement proteins (C1 to C4) causes a lupus-like immune complex disease.', 'C3 deficiency causes severe infections with pus-forming bacteria.', 'Eculizumab, which blocks C5, also raises the risk of Neisseria infection, so patients are vaccinated first.'] },
  'AMB200-059': { c: 'EBV mononucleosis raises the risk of Hodgkin lymphoma',
    w: 'A positive heterophile (Monospot) test with atypical lymphocytes means Epstein–Barr virus. EBV is linked to Hodgkin lymphoma, Burkitt lymphoma and nasopharyngeal cancer.',
    hy: ['EBV enters B cells through CD21. The atypical cells seen on the smear are reacting CD8 T cells.', 'Avoid contact sports because the spleen can rupture. Amoxicillin causes a rash in these patients.', 'Kaposi sarcoma is caused by HHV-8, and liver cancer by hepatitis B and C.'] },
  'AMB200-060': { c: 'Side effects of cyclosporine',
    w: 'Calcineurin inhibitors stop T cells from making IL-2. Cyclosporine in particular causes overgrowth of the gums and extra hair, as well as kidney damage, high blood pressure and high lipids.',
    hy: ['Cyclosporine binds cyclophilin and tacrolimus binds FKBP. Both then block calcineurin.', 'Tacrolimus causes more nerve side effects and diabetes, but no gum or hair growth.', 'Sirolimus blocks mTOR. It does not damage the kidneys, but it can lower blood counts and raise lipids.'] },
});

// ── Blood & lymphoreticular system ──────────────────────────────────────────
add({
  'AMB200-061': { c: 'Isoniazid can cause sideroblastic anemia',
    w: 'Small-cell anemia with high iron and ferritin and low TIBC in a patient on isoniazid points to sideroblastic anemia. Isoniazid uses up vitamin B6, which ALA synthase needs to start making heme. The iron cannot be used, so it builds up in the developing red cells.',
    hy: ['Causes of sideroblastic anemia: isoniazid, alcohol, lead, an inherited ALAS2 mutation and copper deficiency.', 'A Prussian blue stain shows ringed sideroblasts, which are red cell precursors with iron trapped in their mitochondria.', 'Treatment: vitamin B6 (pyridoxine).'],
    t: 'Anemia of chronic disease also has high ferritin and low TIBC, but the serum iron is low, not high.' },
  'AMB200-062': { c: 'Lead poisoning blocks ALA dehydratase and ferrochelatase',
    w: 'Small-cell anemia with blue-dotted red cells (basophilic stippling), belly pain, constipation and slow development is lead poisoning. Lead blocks ALA dehydratase, the enzyme that turns ALA into porphobilinogen.',
    hy: ['Lead also blocks ferrochelatase, so free protoporphyrin rises. Lead lines may appear on the gums and at the ends of long bones.', 'Adults may get wrist or foot drop and headache. Children may get brain swelling.', 'Chelation: succimer for children, and EDTA or dimercaprol for severe cases.'] },
  'AMB200-063': { c: 'ABO hemolytic disease of the newborn',
    w: 'Mothers with blood group O make IgG antibodies against A and B that can cross the placenta. They break down the red cells of a group A baby, causing mild jaundice on day one. The baby is Rh-negative, so Rh disease cannot explain this.',
    hy: ['ABO disease can happen in the first pregnancy. It is usually mild, and the Coombs test is only weakly positive.', 'Rh disease needs the mother to have been sensitized in an earlier pregnancy. It is prevented by giving anti-D (RhoGAM) at 28 weeks and after delivery.', 'High unconjugated bilirubin can damage the brain (kernicterus), so the baby is treated with phototherapy.'] },
  'AMB200-064': { c: 'Alpha-thalassemia trait (two deletions on the same chromosome)',
    w: 'Mild small-cell anemia with a normal ferritin and a normal hemoglobin electrophoresis in an Asian patient is alpha-thalassemia trait. Here both missing genes are on the same chromosome (the cis pattern).',
    hy: ['The cis pattern is common in Asian people and can lead to Hb Barts and hydrops in their children. The trans pattern, with one deletion on each chromosome, is common in African people.', 'Three deletions cause HbH disease (four beta chains). Four deletions cause Hb Barts (four gamma chains) and hydrops fetalis.', 'Beta-thalassemia minor is different: electrophoresis shows a raised HbA2.'] },
  'AMB200-065': { c: 'Sickle cell disease: a non-working spleen leaves Howell–Jolly bodies',
    w: 'Repeated painful swelling of the fingers and pain crises with hemolysis point to sickle cell disease. The spleen is damaged by infarcts early in life, so it can no longer remove the small leftover nuclear pieces (Howell–Jolly bodies) from red cells.',
    hy: ['In HbS, valine replaces glutamate at position 6 of the beta chain. The hemoglobin forms stiff strands when it loses oxygen.', 'Patients are prone to infections with encapsulated bacteria, such as pneumococcus, and to Salmonella bone infection.', 'Hydroxyurea raises fetal hemoglobin. Acute chest syndrome is the most common cause of death.'] },
  'AMB200-066': { c: 'Polycythemia vera (JAK2 V617F)',
    w: 'A very high hematocrit with a low erythropoietin level, clots, itching, a large spleen and high white cell and platelet counts is polycythemia vera. A JAK2 mutation keeps this growth-signal enzyme switched on all the time.',
    hy: ['The JAK2 mutation is also found in essential thrombocythemia and myelofibrosis.', 'In secondary polycythemia, caused by low oxygen or a tumor making erythropoietin, the erythropoietin level is high.', 'Treatment: removing blood, aspirin and hydroxyurea. Patients may have burning red hands and feet and itching after a warm bath.'] },
  'AMB200-067': { c: 'Acute promyelocytic leukemia: t(15;17), PML–RARA',
    w: 'The blasts in acute promyelocytic leukemia come from the myeloid line. They stain positive for myeloperoxidase and often contain needle-like Auer rods. The disease often presents with bleeding from disseminated intravascular coagulation (DIC).',
    hy: ['Treatment: all-trans retinoic acid with arsenic trioxide, which make the blasts mature into normal cells.', 'This treatment can cause differentiation syndrome.', 'Compare: the blasts of acute lymphoblastic leukemia are TdT positive and myeloperoxidase negative. Hairy cell leukemia is TRAP positive.'] },
  'AMB200-068': { c: 'High calcium in multiple myeloma',
    w: 'An older adult with back pain, anemia, kidney failure and high calcium has multiple myeloma. The cancerous plasma cells release signals such as RANKL and IL-6 that switch on osteoclasts, which break down bone and release calcium.',
    hy: ['Protein electrophoresis shows a sharp M spike. Free light chains (Bence Jones protein) appear in the urine, and red cells stack in rows (rouleaux).', 'X-rays show round, punched-out holes in bone. A bone scan may be normal, so use X-ray or MRI.', 'Amyloid deposits and protein casts damage the kidney.'] },
  'AMB200-069': { c: 'Hemolytic uremic syndrome uses up platelets',
    w: 'After bloody diarrhea caused by E. coli O157:H7, Shiga toxin damages the small vessels. Red cells are broken up, platelets fall and the kidneys fail. The clotting factors are not affected, so PT and PTT stay normal, but the bleeding time is long.',
    hy: ['Shiga toxin damages the endothelium, and platelets form small clots in the small vessels.', 'Do not give antibiotics for this E. coli, because killing the bacteria releases more toxin.', 'TTP is similar but is caused by low ADAMTS13, and it brings more nerve symptoms and fever.'] },
  'AMB200-070': { c: 'Hemophilia: factor X cannot be activated',
    w: 'Bleeding into the joints with only a long PTT, and a normal PT and bleeding time, is hemophilia A or B. Factors VIIIa and IXa normally work together to switch on factor X, and here one of them is missing.',
    hy: ['Hemophilia A (factor VIII) and hemophilia B (factor IX) are both X-linked recessive.', 'In a mixing study, adding normal plasma corrects the PTT unless the patient has an inhibitor antibody.', 'Von Willebrand disease would also lengthen the bleeding time.'] },
  'AMB200-071': { c: 'Atrial fibrillation: warfarin, a vitamin K antagonist',
    w: 'Long-term stroke prevention in atrial fibrillation needs an anticoagulant. Warfarin blocks vitamin K epoxide reductase, so the liver cannot activate clotting factors II, VII, IX and X.',
    hy: ['The CHA2DS2-VASc score decides who needs an anticoagulant.', 'Newer oral anticoagulants (apixaban, rivaroxaban, dabigatran) are often preferred now. Warfarin is still used for mechanical valves and mitral stenosis.', 'Aspirin and clopidogrel only block platelets and do not prevent strokes well enough in atrial fibrillation.'] },
  'AMB200-072': { c: 'Anthracyclines damage the heart',
    w: 'Doxorubicin and daunorubicin create free radicals inside heart muscle cells. The more the patient receives, the higher the risk of a weak, enlarged heart with a low ejection fraction.',
    hy: ['Prevention: dexrazoxane, which binds iron. The heart is checked with echocardiography during treatment.', 'Trastuzumab heart damage usually gets better when the drug is stopped. Anthracycline damage does not.', 'Other chemotherapy drugs and their targets: bleomycin damages the lung, cisplatin the kidney and ear, vincristine the nerves and cyclophosphamide the bladder.'] },
  'AMB200-073': { c: 'The testis drains to the para-aortic lymph nodes',
    w: 'The testes form in the abdomen and move down later. Their lymph vessels follow the testicular blood vessels back up to the para-aortic nodes, not to the groin.',
    hy: ['The skin of the scrotum drains to the superficial inguinal nodes in the groin.', 'Do not biopsy a testis through the scrotum, because it changes where the cancer can spread.', 'Tumor markers: beta-hCG is raised in choriocarcinoma and some seminomas. AFP is raised in yolk sac tumors.'] },
});

// ── Cardiovascular system ───────────────────────────────────────────────────
add({
  'AMB200-074': { c: 'Beta-blockers lower renin',
    w: 'The kidney releases renin when beta-1 receptors on the juxtaglomerular cells are stimulated. Blocking these receptors lowers renin, and so lowers angiotensin II and aldosterone.',
    hy: ['ACE inhibitors lower angiotensin II but raise renin, because the normal feedback is lost. ARBs also raise renin.', 'Aliskiren blocks renin directly.', 'Beta-blockers that lower death rates in heart failure with low ejection fraction: metoprolol succinate, carvedilol and bisoprolol.'] },
  'AMB200-075': { c: 'Treacher Collins syndrome: a first pharyngeal arch defect',
    w: 'An underdeveloped lower jaw and cheekbones mean the neural crest cells of the first pharyngeal arch did not form properly. The first arch also forms the malleus and incus, so hearing can be affected.',
    hy: ['First arch: the chewing muscles, the mandibular branch of the trigeminal nerve (V3), the malleus and the incus.', 'Second arch: the stapes, the styloid process, the lesser horn of the hyoid, the muscles of facial expression and the facial nerve.', 'Third arch: the greater horn of the hyoid and stylopharyngeus (nerve IX). Fourth and sixth arches: the larynx and the vagus nerve.'] },
  'AMB200-076': { c: 'Persistent truncus arteriosus: a neural crest defect',
    w: 'A single large vessel leaving the heart means the wall that should split the aorta from the pulmonary artery never formed. This happens when neural crest cells fail to move into the heart.',
    hy: ['Other neural crest heart defects: transposition of the great arteries and tetralogy of Fallot.', 'It is linked to the 22q11 deletion (DiGeorge syndrome).', 'Endocardial cushion defects cause atrioventricular septal defects, which are common in Down syndrome.'] },
  'AMB200-077': { c: 'Tetralogy of Fallot: tet spells',
    w: 'Blue spells when the baby cries or feeds that settle with rest are tet spells. The narrow outflow from the right ventricle makes the right ventricle thicken, which shows as right axis deviation.',
    hy: ['The four parts: pulmonary stenosis, right ventricular hypertrophy, an aorta that sits over both ventricles, and a ventricular septal defect.', 'The chest X-ray shows a boot-shaped heart. Squatting raises the resistance in the body’s arteries and sends more blood to the lungs.', 'The cause is a forward and upward shift of the infundibular septum.'] },
  'AMB200-078': { c: 'Eisenmenger syndrome',
    w: 'A left-to-right shunt that is never closed, here an atrioventricular septal defect in Down syndrome, slowly raises the pressure in the lungs. The right ventricle thickens until the shunt reverses, and the patient becomes blue with clubbed fingers later in life.',
    hy: ['Over time the lung vessels remodel and the high pressure becomes permanent.', 'Signs: high red cell count and clubbing. With a patent ductus arteriosus, only the lower body turns blue.', 'Closing shunts early prevents it.'] },
  'AMB200-079': { c: 'Right heart failure raises the pressure in the capillaries',
    w: 'Obstructive sleep apnea causes high pressure in the lungs, which leads to right heart failure. The high pressure in the veins backs up into the capillaries, and fluid leaks into the legs.',
    hy: ['Right heart failure caused by lung disease is called cor pulmonale. Signs include raised neck veins, a large liver and leg swelling.', 'Low oxygen makes the lung vessels narrow, which drives the high lung pressure in sleep apnea and COPD.', 'A widely split second heart sound with right bundle branch block happens because the pulmonary valve closes late.'] },
  'AMB200-080': { c: 'Bleeding (hypovolemic) shock',
    w: 'Bleeding from the spleen lowers the volume of blood returning to the heart, so CVP and wedge pressure fall and cardiac output falls. The body tightens the arteries to keep blood pressure up, so the resistance rises and the hands and feet feel cold.',
    hy: ['Cardiogenic shock: high wedge pressure, low cardiac output and high resistance.', 'Septic (distributive) shock: low resistance, usually a high cardiac output and warm hands and feet.', 'Obstructive shock (tamponade, tension pneumothorax, pulmonary embolism): high CVP and low cardiac output.'] },
  'AMB200-081': { c: 'Restrictive cardiomyopathy in cardiac sarcoidosis',
    w: 'A pressure–volume loop with a steep filling curve means the ventricle is stiff, and an S4 sound fits this. That is restrictive physiology. Here sarcoidosis has spread into the heart muscle.',
    hy: ['Causes of restrictive cardiomyopathy: amyloidosis, sarcoidosis, hemochromatosis, radiation and Löffler endocarditis.', 'Sarcoidosis in the heart causes conduction blocks, arrhythmias and noncaseating granulomas.', 'Chagas disease, alcohol, viruses, thiamine deficiency and muscular dystrophy cause dilated cardiomyopathy instead.'] },
  'AMB200-082': { c: 'Mitral stenosis: a loud first heart sound',
    w: 'In rheumatic mitral stenosis the left atrial pressure is high, which keeps the mitral leaflets wide open until the ventricle contracts. They then slam shut, making a loud first heart sound, followed in diastole by an opening snap.',
    hy: ['Rheumatic heart disease is the most common cause. It affects the mitral valve more often than the aortic valve.', 'The opening snap is followed by a low rumbling murmur in diastole. The closer the snap is to the second heart sound, the worse the stenosis.', 'Complications: atrial fibrillation, a clot in the left atrium, a hoarse voice and difficulty swallowing.'] },
  'AMB200-083': { c: 'The third heart sound (S3) means volume overload',
    w: 'An S3 early in diastole at the apex is the sound of blood rushing into a ventricle that is already full and stretched. It is a sign of heart failure with a weak, dilated ventricle.',
    hy: ['S3 causes: dilated cardiomyopathy, heart failure with low ejection fraction, mitral regurgitation and high-output states. It is normal in children and in pregnancy.', 'S4 is heard late in diastole when the atrium pushes blood into a stiff ventricle, as in left ventricular hypertrophy or ischemia.', 'Listen with the bell at the apex, with the patient lying on the left side, at the end of breathing out.'] },
  'AMB200-084': { c: 'Dressler syndrome',
    w: 'Pericarditis that appears weeks after a heart attack is autoimmune. The damaged heart releases proteins, and the body makes antibodies against them.',
    hy: ['Pericarditis 1 to 3 days after a heart attack is different. It is caused by direct inflammation from the dead muscle.', 'Signs: chest pain that is worse lying down and better leaning forward, a scratchy rub, and widespread ST elevation with PR depression.', 'Treatment: NSAIDs or aspirin, with colchicine.'] },
  'AMB200-085': { c: 'Glomerulonephritis in endocarditis is caused by immune complexes',
    w: 'Subacute endocarditis can cause glomerulonephritis with red cell casts in the urine. Immune complexes from the blood settle in the glomeruli, which is a type III reaction.',
    hy: ['Other signs of endocarditis: painless spots on the palms (Janeway lesions), painful finger nodules (Osler nodes), retinal spots (Roth spots) and splinter bleeds under the nails.', 'Common organisms: viridans streptococci after dental work, Staphylococcus aureus in people who inject drugs, and Streptococcus gallolyticus with colon cancer.', 'Infected clots that break off cause infarcts and abscesses, not red cell casts.'] },
  'AMB200-086': { c: 'Wolff–Parkinson–White: a delta wave, and avoid AV node blockers',
    w: 'An extra electrical pathway gives a short PR interval and a slurred start to the QRS (the delta wave). If atrial fibrillation starts and verapamil blocks the AV node, all the impulses rush down the extra pathway and can cause ventricular fibrillation.',
    hy: ['For atrial fibrillation with WPW, use procainamide or ibutilide, or give an electrical shock.', 'Avoid adenosine, beta-blockers, calcium channel blockers and digoxin.', 'Holiday heart is atrial fibrillation after binge drinking.'] },
  'AMB200-087': { c: 'Polyarteritis nodosa and hepatitis B',
    w: 'Inflammation that destroys the full wall of medium-sized arteries, with a negative ANCA, kidney damage and bowel ischemia, in a hepatitis B carrier, is polyarteritis nodosa.',
    hy: ['It spares the lungs. Angiography shows many small aneurysms like beads on a string.', 'Treatment: corticosteroids and cyclophosphamide, with antivirals if hepatitis B is present.', 'Microscopic polyangiitis is different: small vessels, positive p-ANCA and lung involvement.'] },
  'AMB200-088': { c: 'Familial chylomicronemia (type I) causes pancreatitis',
    w: 'Without lipoprotein lipase or its activator APOC2, chylomicrons stay in the blood and float as a creamy layer. The very high triglycerides cause acute pancreatitis.',
    hy: ['Other signs: small yellow bumps on the skin (eruptive xanthomas), milky-looking retinal vessels and a large liver and spleen.', 'It does not raise the risk of atherosclerosis.', 'Type IIa (LDL receptor defect) is different: fatty lumps on the tendons and early heart attacks.'] },
  'AMB200-089': { c: 'Statin muscle damage',
    w: 'Statins block HMG-CoA reductase, the key enzyme for making cholesterol. Their classic side effect is muscle pain and damage with a raised CK.',
    hy: ['The risk is higher when statins are combined with fibrates (especially gemfibrozil) or with drugs that block the liver enzyme CYP3A4.', 'Statins can also harm the liver, so liver tests are checked.', 'Statins lower LDL more than any other drug class and reduce deaths from heart disease.'] },
});

// ── Endocrine system ────────────────────────────────────────────────────────
add({
  'AMB200-090': { c: 'External branch of the superior laryngeal nerve',
    w: 'This nerve runs next to the superior thyroid artery and supplies the cricothyroid muscle, which tightens the vocal cords. If it is injured during thyroid surgery, the patient cannot make high-pitched sounds.',
    hy: ['The recurrent laryngeal nerve runs next to the inferior thyroid artery. Injury causes a hoarse voice.', 'Damage to the parathyroid glands causes low calcium with tingling around the mouth.', 'Papillary thyroid cancer: empty-looking nuclei (Orphan Annie eyes), psammoma bodies, spread to lymph nodes and a good outlook.'] },
  'AMB200-091': { c: 'Graves disease: antibodies against the TSH receptor',
    w: 'An overactive thyroid with an evenly enlarged gland and bulging eyes is Graves disease. IgG antibodies switch on the TSH receptor, which is a type II hypersensitivity.',
    hy: ['The same antibodies activate fibroblasts behind the eyes and in the shins, causing eye disease and pretibial swelling.', 'A radioactive iodine scan shows high uptake across the whole gland.', 'Treatment: methimazole (or PTU in the first trimester), radioactive iodine or surgery. Beta-blockers ease the symptoms.'] },
  'AMB200-092': { c: 'Pregnancy raises thyroid-binding globulin',
    w: 'Estrogen makes the liver produce more thyroid-binding globulin. Total T3 and T4 rise, but the free hormone that the body actually uses stays normal, so the woman’s thyroid is working normally.',
    hy: ['The same happens with the birth control pill. Binding globulin falls with nephrotic syndrome, androgens and liver failure.', 'In the first trimester, hCG gently stimulates the TSH receptor, so TSH may be slightly low.', 'Follow free T4 in pregnancy.'] },
  'AMB200-093': { c: 'Kidney bone disease: secondary hyperparathyroidism',
    w: 'In chronic kidney disease the kidneys cannot get rid of phosphate or make active vitamin D. Calcium falls, so the parathyroid glands make more PTH. The spine can look striped on X-ray (rugger-jersey spine).',
    hy: ['Secondary hyperparathyroidism: low calcium, high phosphate and high PTH.', 'Tertiary hyperparathyroidism: after years of secondary disease the glands make PTH on their own, and calcium becomes high.', 'Treatment: phosphate binders, calcitriol and cinacalcet.'] },
  'AMB200-094': { c: 'Central diabetes insipidus after head trauma',
    w: 'The patient makes large amounts of dilute urine and has high sodium, and the urine becomes concentrated after desmopressin. That is central diabetes insipidus. Because it was short-lived, the injury was to the posterior pituitary, where ADH is released, not to the hypothalamus, where it is made.',
    hy: ['In nephrogenic diabetes insipidus the kidney does not respond to desmopressin. Causes include lithium, demeclocycline and high calcium.', 'Water deprivation test: in central diabetes insipidus the urine concentration rises by more than 50% after desmopressin.', 'Damage higher up, in the supraoptic nucleus, usually causes permanent diabetes insipidus.'] },
  'AMB200-095': { c: 'Neuroblastoma: dancing eyes and dancing feet',
    w: 'A toddler with jerky eye movements and muscle jerks (opsoclonus-myoclonus) and a belly mass has neuroblastoma. Under the microscope it shows small round blue cells arranged in Homer Wright rosettes.',
    hy: ['It comes from neural crest cells of the adrenal medulla. The urine contains high levels of VMA and HVA.', 'Amplification of the N-myc gene means a worse outcome. The tumor is positive for bombesin, NSE and S-100.', 'Wilms tumor is different: it forms immature kidney structures and does not cross the midline.'] },
  'AMB200-096': { c: 'Primary adrenal insufficiency (Addison disease)',
    w: 'Dark skin, low blood pressure, a failed cosyntropin test and vitiligo point to autoimmune Addison disease. Low aldosterone causes low sodium, high potassium and acidosis. Low cortisol causes low blood sugar.',
    hy: ['The skin darkens because ACTH is high. ACTH comes from the same precursor molecule (POMC) as melanocyte-stimulating hormone.', 'In secondary (pituitary) insufficiency the skin is not dark and aldosterone is normal.', 'In an adrenal crisis, give IV hydrocortisone and fluids.'] },
  'AMB200-097': { c: 'Glucagonoma',
    w: 'A spreading, peeling red rash (necrolytic migratory erythema), diabetes, weight loss, anemia and diarrhea with a pancreatic mass is a glucagonoma, a tumor of the alpha cells.',
    hy: ['Treatment: octreotide and surgery.', 'Somatostatinoma (delta cells): diabetes, gallstones and fatty stools.', 'Insulinoma (beta cells): low blood sugar with a high C-peptide.'] },
  'AMB200-098': { c: 'Type 2 diabetes: amyloid in the islets',
    w: 'In type 2 diabetes the pancreatic islets fill with amyloid made from islet amyloid polypeptide (amylin). The patient’s numb feet are nerve damage, a small-vessel complication of diabetes.',
    hy: ['Type 1 diabetes is autoimmune, with anti-GAD antibodies, HLA-DR3 and DR4, and lymphocytes inside the islets.', 'Diabetic nerve damage comes from sorbitol building up in nerves and from damage to small vessels.', 'Adiponectin is low in obesity. It normally makes the body more sensitive to insulin.'] },
  'AMB200-099': { c: 'ACTH made by small cell lung cancer',
    w: 'Cushing syndrome with a high ACTH that is not lowered by high-dose dexamethasone, plus very low potassium, means a tumor outside the pituitary is making ACTH. The classic source is small cell lung cancer.',
    hy: ['A pituitary tumor (Cushing disease): high-dose dexamethasone does lower cortisol.', 'An adrenal tumor: ACTH is low.', 'Small cell lung cancer can also make ADH (SIADH) and cause Lambert–Eaton syndrome.'] },
  'AMB200-100': { c: 'Hereditary hemochromatosis (HFE gene)',
    w: 'Diabetes, bronze skin and liver disease together are bronze diabetes, the picture of hemochromatosis. A mutation in the HFE gene (C282Y) means the gut absorbs too much iron.',
    hy: ['The liver stains blue with Prussian blue. Ferritin and transferrin saturation are both high.', 'Complications: cirrhosis, liver cancer, heart failure, joint disease and low sex hormones.', 'Treatment: regular removal of blood, with iron-binding drugs (deferoxamine or deferasirox) if needed.'] },
  'AMB200-101': { c: 'MEN 2B: a RET mutation',
    w: 'Episodes of headache, palpitations, sweating and high blood pressure (pheochromocytoma), medullary thyroid cancer, bumps on the lips and tongue and a tall thin build are MEN 2B. It is caused by a mutation in the RET gene.',
    hy: ['MEN 2A: medullary thyroid cancer, pheochromocytoma and overactive parathyroid glands.', 'MEN 1 (menin gene): tumors of the pituitary, pancreas and parathyroid glands.', 'People with a RET mutation have the thyroid removed early. Always check for a pheochromocytoma before any surgery.'] },
  'AMB200-102': { c: 'A pituitary tumor making TSH acts through a G protein receptor',
    w: 'An overactive thyroid with a mass in the pituitary is a TSH-secreting adenoma. TSH acts on thyroid cells through a receptor linked to the stimulatory G protein (Gs).',
    hy: ['Gs receptors, which raise cAMP: TSH, ACTH, FSH, LH, PTH, glucagon, V2, beta receptors, calcitonin and hCG.', 'Gq receptors: GnRH, oxytocin, TRH, V1, alpha-1, H1, M1, M3 and angiotensin II.', 'Tyrosine kinase receptors: insulin and IGF-1. JAK/STAT receptors: growth hormone, prolactin and erythropoietin.'] },
  'AMB200-103': { c: 'Sulfonylureas close ATP-sensitive potassium channels',
    w: 'Episodes of low blood sugar and weight gain after starting a new diabetes tablet point to a sulfonylurea. It closes the ATP-sensitive potassium channels on the pancreatic beta cells. The cell becomes more positive (depolarizes), calcium enters and the cell releases insulin, whatever the blood sugar is.',
    hy: ['Examples: glyburide, glipizide and glimepiride. Low blood sugar is more likely in kidney failure, because the drug builds up.', 'The older first-generation drugs can cause a disulfiram-like reaction with alcohol.', 'Diabetes drugs that do not cause weight gain: metformin, GLP-1 agonists and SGLT2 inhibitors.'] },
});

// ── Gastrointestinal system ─────────────────────────────────────────────────
add({
  'AMB200-104': { c: 'Chagas disease causes secondary achalasia',
    w: 'An immigrant from Central America has trouble swallowing both solids and liquids, a bird-beak esophagus on imaging, and heart failure. This is Chagas disease. The parasite Trypanosoma cruzi destroys the nerves in the wall of the esophagus.',
    hy: ['In achalasia the nerves that relax the lower esophageal sphincter are lost, so the sphincter stays closed.', 'Chagas disease also causes a very large colon and a weak, dilated heart. It is spread by the kissing (reduviid) bug.', 'Treatment: benznidazole or nifurtimox.'] },
  'AMB200-105': { c: 'Mallory–Weiss tear',
    w: 'Vomiting blood after forceful vomiting in a patient with bulimia, with calluses on the knuckles and worn tooth enamel, is a Mallory–Weiss tear. It is a shallow tear in the lining where the esophagus meets the stomach.',
    hy: ['Boerhaave syndrome is a full tear through the esophageal wall. Air leaks into the chest and under the skin, and a crunching sound may be heard over the heart.', 'Bulimia also causes low potassium with metabolic alkalosis and swollen salivary glands.', 'A Mallory–Weiss tear usually stops bleeding on its own.'] },
  'AMB200-106': { c: 'Gastric ulcer: Helicobacter pylori',
    w: 'Pain right after eating, with weight loss, points to a gastric ulcer. Helicobacter pylori infection is the strongest risk factor, followed by NSAIDs.',
    hy: ['Gastric ulcers hurt during meals and cause weight loss. They are biopsied to rule out cancer.', 'Duodenal ulcers feel better with food and are almost always caused by H. pylori.', 'Treatment for H. pylori: a proton pump inhibitor with clarithromycin and amoxicillin (or metronidazole).'] },
  'AMB200-107': { c: 'Whipple disease',
    w: 'Poor absorption of food, joint pain and foamy macrophages that stain pink with PAS in the gut lining are Whipple disease. It is caused by Tropheryma whipplei, a gram-positive bacterium that lives inside cells.',
    hy: ['The classic patient is an older white man. It can also affect the heart and brain.', 'The foamy macrophages block the lymph vessels in the gut, so fat is poorly absorbed.', 'Treatment: ceftriaxone, then TMP-SMX for a year.'] },
  'AMB200-108': { c: 'Hirschsprung disease',
    w: 'No meconium in the first 48 hours, a burst of stool after a rectal exam and a narrow lower colon with a wide colon above it are Hirschsprung disease. Part of the colon has no nerve cells, because neural crest cells did not travel all the way down.',
    hy: ['A suction biopsy of the rectum shows no ganglion cells. It is linked to RET mutations and is more common in Down syndrome.', 'Meconium ileus is different and suggests cystic fibrosis.', 'Other causes of blocked bowel in newborns: malrotation (green vomiting) and duodenal atresia (a double bubble on X-ray).'] },
  'AMB200-109': { c: 'Crohn disease is driven by Th1 cells',
    w: 'Inflammation through the full thickness of the bowel wall with granulomas that have no central necrosis is Crohn disease. It is driven by Th1 cells (interferon-gamma and IL-12) and by Th17 cells.',
    hy: ['Crohn disease: patchy skip lesions, a cobblestone surface, fistulas, the end of the small bowel affected, and narrowing (string sign).', 'Ulcerative colitis: continuous disease starting at the rectum, only the inner lining affected, pseudopolyps, and a link with primary sclerosing cholangitis.', 'Anti-Saccharomyces antibodies (ASCA) are seen in Crohn disease, and p-ANCA in ulcerative colitis.'] },
  'AMB200-110': { c: 'Portal hypertension: caput medusae',
    w: 'Primary sclerosing cholangitis, linked to ulcerative colitis, has caused cirrhosis and high pressure in the portal vein. Blood finds another way back to the heart through the veins around the navel, which swell into the veins on the belly wall (caput medusae).',
    hy: ['Places where the portal and body veins connect: the lower esophagus (varices), around the navel (caput medusae) and the rectum.', 'A TIPS procedure connects the portal vein to a hepatic vein to lower the pressure.', 'Ascites forms because of high pressure, low albumin and salt retention by the kidneys.'] },
  'AMB200-111': { c: 'Chronic hepatitis B blood tests',
    w: 'Hepatitis B surface antigen and viral DNA have been present for more than 6 months. HBeAg is positive, which means the virus is actively copying. Anti-HBc is now IgG, not IgM, and there is no anti-HBs. This is chronic active hepatitis B.',
    hy: ['Anti-HBs alone means the person was vaccinated. Anti-HBs with anti-HBc IgG means the person had the infection and recovered.', 'In the window period, only anti-HBc IgM is positive.', 'HBeAg means the person is highly infectious. Anti-HBe means the person is less infectious.'] },
  'AMB200-112': { c: 'Acute cholecystitis: a stone blocks the cystic duct',
    w: 'Fever, right upper belly pain and a high white count, with a gallbladder that fills late or not at all on a HIDA scan, mean a gallstone is blocking the cystic duct.',
    hy: ['Risk factors: female, fertile, forty and overweight. Pressing under the right ribs stops the breath (Murphy sign).', 'A normal bilirubin and ALP mean the common bile duct is not blocked.', 'Gallstone ileus is different: a stone passes through a fistula into the bowel and gets stuck near the end of the small bowel.'] },
  'AMB200-113': { c: 'Painless jaundice with a palpable gallbladder: pancreatic cancer',
    w: 'Painless jaundice, itching and a gallbladder that can be felt but is not tender (Courvoisier sign) point to cancer in the head of the pancreas blocking the bile duct.',
    hy: ['Smoking is the strongest risk factor, and the tumor marker CA 19-9 is raised.', 'It can cause clots that move from vein to vein (Trousseau syndrome).', 'Gallstone disease usually leaves a small, scarred gallbladder, not a large one.'] },
});

// ── Skin & musculoskeletal system ───────────────────────────────────────────
add({
  'AMB200-114': { c: 'Rubella',
    w: 'In an unvaccinated child, a rash that starts on the face or behind the ears and spreads down, with tender lymph nodes behind the ears and at the back of the head, is rubella.',
    hy: ['Rubella is a togavirus. Infection in pregnancy can cause a patent ductus arteriosus, cataracts, deafness and a blueberry-muffin rash in the baby.', 'Measles is different: cough, runny nose, red eyes and white spots inside the cheeks (Koplik spots) before the rash.', 'Roseola (HHV-6) brings a high fever first and the rash after. Parvovirus B19 causes a slapped-cheek rash.'] },
  'AMB200-115': { c: 'Tinea versicolor: Malassezia',
    w: 'Pale, slightly scaly patches that appear after hot, humid weather are caused by overgrowth of the yeast Malassezia. It makes azelaic acid, which blocks the pigment cells from making melanin.',
    hy: ['A KOH prep shows hyphae and round yeast, often called spaghetti and meatballs.', 'Treatment: selenium sulfide or an azole cream.', 'Vitiligo is different: complete loss of color, no scale and an autoimmune cause.'] },
  'AMB200-116': { c: 'Pemphigus vulgaris: antibodies against desmosomes',
    w: 'Fragile, easily broken blisters with sores in the mouth and a split inside the epidermis are pemphigus vulgaris. Antibodies attack desmoglein 1 and 3, the proteins that hold skin cells together.',
    hy: ['Rubbing the skin makes it peel (positive Nikolsky sign). Immunofluorescence shows IgG in a net-like pattern between the cells.', 'Bullous pemphigoid is different: tense blisters, no mouth sores and a straight line of IgG along the base of the epidermis.', 'Treatment: corticosteroids by mouth and rituximab.'] },
  'AMB200-117': { c: 'Basal cell carcinoma',
    w: 'A slow-growing, pearly bump with small visible blood vessels and a rolled edge on sun-exposed skin of the face is a basal cell carcinoma.',
    hy: ['It is the most common skin cancer. It rarely spreads and usually appears on the upper face and nose.', 'Under the microscope, the cells at the edge of the tumor nests line up like a fence (palisading).', 'Squamous cell carcinoma is different: it favors the lower lip, often ulcerates, shows keratin pearls and can spread.'] },
  'AMB200-118': { c: 'Neuroleptic malignant syndrome: dantrolene',
    w: 'Fever, stiff muscles, unstable pulse and blood pressure, confusion and a high CK in someone taking an antipsychotic is neuroleptic malignant syndrome. Dantrolene blocks the ryanodine receptor in muscle, so calcium is not released and the muscle relaxes.',
    hy: ['Also stop the antipsychotic and give bromocriptine, a dopamine agonist.', 'Malignant hyperthermia, triggered by succinylcholine or inhaled anesthetics, is also treated with dantrolene.', 'Serotonin syndrome is different: brisk reflexes and jerking (clonus) instead of lead-pipe stiffness.'] },
  'AMB200-119': { c: 'Myasthenia gravis: a smaller end plate potential',
    w: 'Drooping eyelids and jaw weakness that get worse as the day goes on are myasthenia gravis. Antibodies block the acetylcholine receptors on the muscle, so each nerve signal produces a smaller end plate potential.',
    hy: ['It is linked to thymus tumors and an enlarged thymus, so the chest is scanned with CT.', 'Treatment: pyridostigmine, drugs that calm the immune system, and removal of the thymus.', 'Lambert–Eaton syndrome is different: antibodies attack calcium channels on the nerve ending, strength improves with use, and it is linked to small cell lung cancer.'] },
  'AMB200-120': { c: 'Serotonin syndrome: a triptan plus an SSRI',
    w: 'High temperature, agitation, sweating, brisk reflexes with jerking (clonus) and stomach upset after adding sumatriptan to fluoxetine is serotonin syndrome.',
    hy: ['Other triggers: MAO inhibitors, linezolid, tramadol, meperidine, dextromethorphan and St John’s wort.', 'Treatment: cyproheptadine, which blocks serotonin receptors, and benzodiazepines.', 'Triptans tighten blood vessels, so avoid them in patients with coronary artery disease.'] },
  'AMB200-121': { c: 'Calcium binds troponin C',
    w: 'When calcium binds troponin C, tropomyosin moves off the sites on actin where myosin attaches. Myosin can then grab actin, and the muscle contracts.',
    hy: ['How the signal reaches the muscle: acetylcholine triggers an action potential that runs down the T tubules, the DHP receptor pulls on the ryanodine receptor, and calcium is released.', 'Smooth muscle works differently: calcium binds calmodulin, which switches on myosin light chain kinase.', 'Myosin needs ATP to let go of actin, which is why muscles go stiff after death (rigor mortis).'] },
  'AMB200-122': { c: 'Lupus: anti-Smith antibodies are the most specific',
    w: 'A young woman with a flare after sun exposure, joint pain, mouth ulcers and tiredness has systemic lupus erythematosus. Anti-Smith (and anti-double-stranded DNA) antibodies are the ones that are specific for lupus.',
    hy: ['ANA is positive in almost everyone with lupus, so it is a good screening test, but many people without lupus also have it.', 'Anti-double-stranded DNA rises with lupus kidney disease and with disease activity.', 'Anti-histone antibodies point to drug-induced lupus (from hydralazine, procainamide or isoniazid).'] },
  'AMB200-123': { c: 'Limited systemic sclerosis (CREST syndrome)',
    w: 'Raynaud phenomenon, tight skin on the fingers and hard white lumps at the fingertips (calcinosis) are limited systemic sclerosis. Small red spots of dilated vessels (telangiectasias) are also part of CREST.',
    hy: ['CREST stands for calcinosis, Raynaud phenomenon, esophageal problems, sclerodactyly and telangiectasia. Anti-centromere antibodies are typical.', 'Diffuse scleroderma is different: anti-Scl-70 antibodies, lung scarring and sudden kidney failure.', 'The limited form can cause high blood pressure in the lungs.'] },
  'AMB200-124': { c: 'Rheumatoid arthritis: pannus',
    w: 'Morning stiffness in the knuckles and wrists on both sides, with eroded bone on X-ray, is rheumatoid arthritis. The joint lining grows into a thick, inflamed layer called pannus that eats into cartilage and bone.',
    hy: ['Anti-CCP antibodies are the most specific test. Rheumatoid factor is an IgM antibody against the tail of IgG.', 'It is linked to HLA-DR4 and does not affect the joints closest to the fingertips (the DIP joints).', 'Treatment: methotrexate first, then biologic drugs such as TNF blockers.'] },
  'AMB200-125': { c: 'Reactive arthritis: HLA-B27',
    w: 'Painful urination, red eyes and arthritis after a chlamydia (or bowel) infection are reactive arthritis. It belongs to the group of HLA-B27 joint diseases with a negative rheumatoid factor.',
    hy: ['Memory aid: can’t see (red eyes), can’t pee (urethritis), can’t climb a tree (arthritis).', 'Triggers: Chlamydia, Shigella, Salmonella, Yersinia and Campylobacter.', 'Other HLA-B27 diseases: ankylosing spondylitis, psoriatic arthritis and the arthritis of inflammatory bowel disease.'] },
  'AMB200-126': { c: 'Dermatomyositis can be a sign of cancer',
    w: 'A purple rash on the eyelids, red bumps over the knuckles (Gottron papules) and weakness of the shoulders and hips are dermatomyositis. It is linked to cancer, especially ovarian cancer in women.',
    hy: ['Antibodies: anti-Mi-2 is specific, and anti-Jo-1 goes with lung scarring.', 'Biopsy shows inflammation around the muscle bundles with shrinking of the fibers at their edges. Polymyositis shows inflammation inside the bundles instead.', 'CK and aldolase are high. Always look for an underlying cancer.'] },
  'AMB200-127': { c: 'Paget disease of bone',
    w: 'An older adult with a growing hat size, hearing loss, bowed long bones and bone pain has Paget disease. Bone is broken down and rebuilt in a chaotic way, leaving a mosaic of woven and normal bone.',
    hy: ['Blood tests: only the alkaline phosphatase is raised. Calcium and phosphate are normal.', 'Complications: heart failure from the high blood flow, osteosarcoma and fractures.', 'Treatment: bisphosphonates.'] },
});

// ── Nervous system & special senses ─────────────────────────────────────────
add({
  'AMB200-128': { c: 'Loss of the upper right quarter of vision: the left Meyer loop',
    w: 'Both eyes have lost vision in the upper right quarter (a pie in the sky defect). That means the lower fibers of the optic radiation, called the Meyer loop, are damaged in the left temporal lobe.',
    hy: ['A Meyer loop lesion in the temporal lobe causes loss of the upper quarter on the opposite side. A lesion in the parietal fibers causes loss of the lower quarter.', 'A lesion at the optic chiasm causes loss of both outer halves of vision. A lesion in the optic tract causes loss of the same half in both eyes.', 'A blocked posterior cerebral artery causes loss of the same half in both eyes, with the center of vision spared.'] },
  'AMB200-129': { c: 'Horner syndrome from a Pancoast tumor',
    w: 'A smoker with a drooping eyelid, a small pupil (the difference is clearer in the dark) and shoulder and arm pain has a tumor at the top of the lung. It is pressing on the sympathetic nerves and the stellate ganglion.',
    hy: ['Horner syndrome: drooping eyelid, small pupil and no sweating on that side of the face.', 'A Pancoast tumor can also press on the brachial plexus (pain and weakness in the arm), the superior vena cava and the nerve to the voice box.', 'A painful Horner syndrome with neck pain suggests a tear in the carotid artery.'] },
  'AMB200-130': { c: 'Third nerve palsy from a posterior communicating artery aneurysm',
    w: 'An eye that points down and out, with a drooping lid and a large pupil that does not react, means the third cranial nerve is being squeezed. The fibers that shrink the pupil run on the outside of the nerve, so they are hit first.',
    hy: ['A third nerve palsy from diabetes spares the pupil, because it damages the center of the nerve.', 'An aneurysm of the posterior communicating artery can burst and cause a subarachnoid hemorrhage.', 'Brain herniation (uncal herniation) can also squeeze the third nerve.'] },
  'AMB200-131': { c: 'Facial nerve pressed at the cerebellopontine angle',
    w: 'Facial weakness, loss of taste and a dry eye with a mass at the back of the skull mean the seventh cranial nerve is being pressed near the internal acoustic canal. This is above the point where the branches to the tear gland and the tongue leave the nerve.',
    hy: ['A lesion high up on the seventh nerve weakens the whole face and also affects taste, tears and sensitivity to loud sounds.', 'A vestibular schwannoma usually starts with hearing loss and ringing in the ears from the eighth nerve.', 'A stroke (upper motor neuron) facial weakness spares the forehead.'] },
  'AMB200-132': { c: 'Position sense from the leg travels on the same side',
    w: 'The area marked carries position sense from the leg on the same side, through the dorsal columns and the dorsal spinocerebellar tract. Damage there leaves the patient unsure where that leg is.',
    hy: ['The dorsal columns carry vibration and position sense. They cross to the other side in the medulla.', 'The spinothalamic tract carries pain and temperature. It crosses at the level of the spinal cord where it enters.', 'Removing the stomach can cause vitamin B12 deficiency, which damages the dorsal columns.'] },
  'AMB200-133': { c: 'Huntington disease: shrinking of the caudate',
    w: 'Writhing movements, a change in personality and memory loss, with an affected father, is Huntington disease. MRI shows a shrunken caudate nucleus with enlarged lateral ventricles.',
    hy: ['It is caused by a CAG repeat in the HTT gene on chromosome 4. It is autosomal dominant and often starts earlier when passed through the father.', 'GABA and acetylcholine are low and dopamine is relatively high. Tetrabenazine treats the movements.', 'The risk of suicide is high.'] },
  'AMB200-134': { c: 'Epidural hematoma: the lucid interval',
    w: 'After a head injury the patient was knocked out, then woke and seemed fine, then quickly got worse. This is an epidural bleed from an artery, usually the middle meningeal artery, between the skull and the dura.',
    hy: ['On CT it looks like a lens (biconvex) and does not cross the skull suture lines.', 'A subdural bleed is different: it comes from torn bridging veins, looks like a crescent, crosses suture lines and is common in older people and heavy drinkers.', 'A fracture at the pterion, at the side of the skull, tears the middle meningeal artery.'] },
  'AMB200-135': { c: 'Anterior cerebral artery stroke',
    w: 'Weakness and numbness of the opposite leg more than the arm, loss of bladder control, lack of motivation and speech that is slow to start point to a stroke in the left anterior cerebral artery.',
    hy: ['Middle cerebral artery stroke: face and arm worse than leg, with aphasia if the dominant side is affected or neglect if the other side is.', 'Posterior cerebral artery stroke: loss of half the visual field on the opposite side, with the center spared.', 'A stroke in the small lenticulostriate arteries can cause weakness only (pure motor lacunar stroke).'] },
  'AMB200-136': { c: 'Multiple sclerosis',
    w: 'Nerve symptoms that come and go, in different places at different times, that get worse with heat, plus optic neuritis, are multiple sclerosis. T cells (Th1 and Th17) attack the myelin of the brain and spinal cord.',
    hy: ['Spinal fluid shows oligoclonal IgG bands. MRI shows plaques around the ventricles.', 'Typical signs: eyes that cannot move together properly (internuclear ophthalmoplegia), choppy speech and a tremor when reaching.', 'Flares are treated with high-dose steroids. Long-term drugs include interferon-beta, natalizumab and ocrelizumab.'] },
  'AMB200-137': { c: 'Neurofibromatosis type 2',
    w: 'Schwannomas on both hearing nerves, causing hearing loss and poor balance, with a mutation in the NF2 gene (merlin) on chromosome 22, are neurofibromatosis type 2. Meningiomas are also common.',
    hy: ['NF2: schwannomas, meningiomas, ependymomas and cataracts at a young age.', 'NF1 (chromosome 17) is different: café-au-lait spots, neurofibromas, small iris bumps (Lisch nodules) and optic nerve tumors.', 'Von Hippel–Lindau (chromosome 3): blood vessel tumors in the brain and kidney cancer.'] },
  'AMB200-138': { c: 'Anterior spinal artery syndrome',
    w: 'After aortic surgery, the patient lost movement and pain and temperature sensation below a certain level, but vibration and position sense are normal. The blood supply to the front of the spinal cord was cut off.',
    hy: ['The dorsal columns survive because they get blood from the posterior spinal arteries.', 'Brown-Séquard syndrome (one half of the cord): weakness and loss of position sense on the same side, and loss of pain and temperature on the other side.', 'Central cord syndrome: the arms are weaker than the legs, often after the neck is bent back in an older person.'] },
  'AMB200-139': { c: 'Meningioma comes from arachnoid cells',
    w: 'A clearly outlined mass outside the brain tissue causing seizures in a middle-aged woman is a meningioma. It grows from arachnoid cap cells, which form swirls and small calcified bodies (psammoma bodies).',
    hy: ['MRI shows a tail along the dura. It is more common in women because it has progesterone receptors.', 'It is the most common benign tumor that starts in the brain in adults.', 'Schwannoma is different: S-100 positive, with dense and loose areas (Antoni A and B).'] },
  'AMB200-140': { c: 'Narcolepsy: loss of orexin',
    w: 'Sudden sleep attacks, sudden loss of muscle tone when laughing (cataplexy) and being unable to move on waking are narcolepsy. The nerve cells in the hypothalamus that make orexin (hypocretin) have been lost.',
    hy: ['Dream (REM) sleep starts very soon after falling asleep. Patients may see things as they fall asleep or wake up.', 'Treatment: regular sleep habits, modafinil, and sodium oxybate for cataplexy.', 'Other spinal fluid markers: 14-3-3 protein points to Creutzfeldt–Jakob disease, and oligoclonal bands to multiple sclerosis.'] },
  'AMB200-141': { c: 'Polio: lower motor neuron signs',
    w: 'Polio destroys the motor nerve cells in the front of the spinal cord. This gives lower motor neuron signs: floppy weakness, weak reflexes, muscle twitching and wasting. Sensation is normal.',
    hy: ['Polio is a picornavirus spread through stool. The weakness is uneven, and if the brainstem is affected breathing can fail.', 'Upper motor neuron signs are different: stiffness, brisk reflexes and an upgoing big toe (Babinski sign).', 'The injected killed vaccine (Salk) is used in the US. The oral live vaccine (Sabin) also gives gut IgA protection.'] },
  'AMB200-142': { c: 'Guillain–Barré syndrome attacks Schwann cells',
    w: 'Weakness that climbs up from the legs with lost reflexes, after Campylobacter diarrhea, with high protein but normal cells in the spinal fluid, is Guillain–Barré syndrome. The immune system attacks the myelin of peripheral nerves, which is made by Schwann cells.',
    hy: ['The antibodies against the infection also react with nerve myelin (molecular mimicry). Breathing failure is the main danger, so lung capacity is checked often.', 'Treatment: IVIG or plasmapheresis. Steroids do not help.', 'Unstable heart rate and blood pressure are common, and many patients have weakness of both sides of the face.'] },
  'AMB200-143': { c: 'Down syndrome leads to early Alzheimer disease',
    w: 'People with Down syndrome have an extra chromosome 21, which carries the APP gene. They make extra amyloid, so amyloid plaques build up and Alzheimer dementia starts in the 40s.',
    hy: ['Alzheimer disease: amyloid plaques outside the nerve cells and tangles of tau protein inside them.', 'The ApoE4 gene raises the risk and ApoE2 protects.', 'Other proteins: alpha-synuclein is found in Lewy body disease and Parkinson disease, and TDP-43 in frontotemporal dementia and ALS.'] },
  'AMB200-144': { c: 'Fracture of the middle of the humerus: radial nerve',
    w: 'The radial nerve runs in a groove around the middle of the humerus. When it is injured, the wrist drops and the grip is weak, because the wrist extensors are needed to hold the wrist steady while gripping.',
    hy: ['A fracture of the surgical neck of the humerus injures the axillary nerve, which supplies the deltoid and the skin of the upper outer arm.', 'A fracture just above the elbow injures the median nerve. An injury at the inner elbow bump injures the ulnar nerve.', 'The radial nerve supplies the muscles that straighten the wrist and fingers and the skin on the back of the hand.'] },
  'AMB200-145': { c: 'Organophosphate poisoning: atropine',
    w: 'A farm worker has diarrhea, urination, small pupils, wheezing, a slow heart, vomiting, tears and drooling. Organophosphates block acetylcholinesterase, so acetylcholine builds up. Atropine blocks the muscarinic receptors and reverses these effects.',
    hy: ['Also give pralidoxime, which reactivates acetylcholinesterase if given before the enzyme is permanently damaged.', 'Atropine does not fix the nicotinic effects, such as muscle weakness.', 'Remove the patient’s clothing and wash the skin to stop further exposure.'] },
});

// ── Behavioral health ───────────────────────────────────────────────────────
add({
  'AMB200-146': { c: 'Stages of change: contemplation',
    w: 'He knows he has a problem but is not yet ready to do anything about it. This stage is called contemplation.',
    hy: ['The stages: precontemplation (not aware of a problem), contemplation (unsure), preparation (making plans), action, maintenance and relapse.', 'Motivational interviewing works best in the precontemplation and contemplation stages.', 'Ask open questions and avoid lecturing.'] },
  'AMB200-147': { c: 'Borderline personality disorder: splitting',
    w: 'Unstable relationships, acting on impulse, repeated self-harm and threats of suicide are borderline personality disorder. Its typical defense is splitting, where people are seen as all good or all bad.',
    hy: ['Treatment: dialectical behavior therapy.', 'Patients fear being left and often feel empty.', 'Other defenses: displacement is moving feelings onto a safer target, and reaction formation is acting the opposite of how one feels.'] },
  'AMB200-148': { c: 'Schizophreniform disorder',
    w: 'Psychotic symptoms that have lasted more than 1 month but less than 6 months are schizophreniform disorder.',
    hy: ['Brief psychotic disorder lasts less than 1 month. Schizophrenia lasts 6 months or more, including the early warning phase.', 'Schizoaffective disorder: a major mood episode, plus at least 2 weeks of psychosis without mood symptoms.', 'Delusional disorder: believable delusions with otherwise normal day-to-day functioning.'] },
  'AMB200-149': { c: 'Major depressive disorder',
    w: 'Five or more symptoms for at least 2 weeks, here loss of interest, poor concentration, waking early, slowed movement and poor appetite, are major depressive disorder.',
    hy: ['Symptoms to check: sleep, interest, guilt, energy, concentration, appetite, slowed or restless movement, and thoughts of suicide.', 'Persistent depressive disorder is milder and lasts at least 2 years.', 'PTSD needs a past trauma with flashbacks, avoidance and being constantly on edge.'] },
  'AMB200-150': { c: 'Antisocial personality disorder',
    w: 'Ignoring other people’s rights, lying, crime, irresponsibility and no remorse, in someone aged 18 or over who had conduct disorder before 15, is antisocial personality disorder.',
    hy: ['Under 18 the diagnosis is conduct disorder.', 'It is more common in males and often goes with substance use.', 'Narcissistic personality disorder is different: a sense of being special, a need for admiration and little empathy, but not usually crime.'] },
  'AMB200-151': { c: 'Anorexia nervosa causes bone loss',
    w: 'A very low BMI, missed periods and fine body hair (lanugo) are anorexia nervosa. The brain stops signaling the ovaries, so estrogen falls and bone is lost. Stress fractures are the classic complication.',
    hy: ['Other effects: slow heart rate, low blood pressure, low body temperature, high cortisol, low T3 and a long QT interval.', 'Refeeding syndrome: when eating restarts, phosphate (with potassium and magnesium) can drop sharply and cause heart failure and arrhythmias.', 'Female athlete triad: low energy intake, missed periods and low bone density.'] },
  'AMB200-152': { c: 'An antidepressant can trigger mania in bipolar disorder',
    w: 'Giving an antidepressant such as venlafaxine to someone with undiagnosed bipolar disorder can flip them into mania. Signs are little sleep, a sense of grandness, spending sprees and risky behavior.',
    hy: ['Always ask about past mania or hypomania before starting an antidepressant.', 'Depression in bipolar disorder is treated with lithium, quetiapine, lurasidone or lamotrigine.', 'Bupropion makes seizures more likely, so avoid it in seizure disorders and eating disorders.'] },
  'AMB200-153': { c: 'Monitoring lithium',
    w: 'Lithium can cause an underactive thyroid and nephrogenic diabetes insipidus. TSH, creatinine and lithium levels are therefore checked regularly.',
    hy: ['The safe range is narrow. Thiazides, ACE inhibitors, NSAIDs and dehydration all raise the level.', 'Signs of toxicity: tremor, then unsteadiness, confusion and seizures.', 'In pregnancy it can cause Ebstein anomaly of the heart.'] },
  'AMB200-154': { c: 'Low-potency antipsychotics cause anticholinergic effects',
    w: 'The patient’s restlessness (akathisia) on a high-potency antipsychotic, trifluoperazine, improves on a low-potency drug such as chlorpromazine. The trade-off is more sleepiness and anticholinergic side effects.',
    hy: ['High-potency drugs (haloperidol, fluphenazine, trifluoperazine) cause more movement side effects.', 'Low-potency drugs (chlorpromazine, thioridazine) cause more anticholinergic effects, sleepiness and low blood pressure.', 'Akathisia can also be treated with propranolol or a benzodiazepine.'] },
  'AMB200-155': { c: 'Alcohol withdrawal with liver disease: lorazepam',
    w: 'Shaking, agitation, a fast heart rate and hallucinations 2 days after admission are alcohol withdrawal. In liver disease, use a benzodiazepine that the liver does not turn into active products, such as lorazepam, oxazepam or temazepam.',
    hy: ['Memory aid: LOT, for lorazepam, oxazepam and temazepam, which are safe in liver failure.', 'Chlordiazepoxide and diazepam last a long time and depend on the liver to be broken down.', 'Delirium tremens starts 2 to 4 days after the last drink and can be fatal.'] },
  'AMB200-156': { c: 'MDMA (ecstasy) intoxication',
    w: 'Euphoria, feeling close to others, wanting to touch, high temperature, large pupils, high blood pressure and low sodium are MDMA intoxication. The low sodium comes from extra ADH plus drinking lots of water.',
    hy: ['MDMA releases serotonin, so it can cause serotonin syndrome.', 'PCP causes violence and jerky eye movements. LSD causes visual hallucinations with little physical danger.', 'Treatment: cooling, benzodiazepines and limiting water for the low sodium.'] },
});

// ── Renal & urinary system ──────────────────────────────────────────────────
add({
  'AMB200-157': { c: 'Acute tubular necrosis: muddy brown casts',
    w: 'Low blood flow to the kidneys went on for so long that the tubule cells died. That is ischemic acute tubular necrosis. The dead cells peel off into the urine and form muddy brown granular casts.',
    hy: ['The parts of the tubule most at risk are the straight part of the proximal tubule and the thick ascending limb.', 'Phases: the injury, then a phase of little urine and high potassium, then recovery with a lot of urine and low potassium.', 'The fractional excretion of sodium is above 2% in acute tubular necrosis and below 1% when the problem is only low blood flow (prerenal).'] },
  'AMB200-158': { c: 'Aspirin poisoning: a mixed acid–base problem',
    w: 'Ringing in the ears, vomiting and fever, then seizures, are aspirin poisoning. Aspirin first stimulates the breathing center, causing respiratory alkalosis. Later the acids build up, adding a metabolic acidosis with a raised anion gap.',
    hy: ['Anion gap in this patient: 140 minus (102 plus 18) equals 20, which is high.', 'Treatment: sodium bicarbonate to make the urine alkaline, and dialysis if severe.', 'Aspirin uncouples energy production in mitochondria, which releases heat and raises body temperature.'] },
  'AMB200-159': { c: 'Low potassium: alpha-intercalated cells take potassium back',
    w: 'Extra insulin pushed potassium into the cells, causing weakness and flat T waves. The kidney responds by making more of the hydrogen–potassium pump in the alpha-intercalated cells, which takes potassium back from the urine.',
    hy: ['Insulin, beta-2 agonists and alkalosis all move potassium into cells.', 'ECG signs of low potassium: flat T waves, U waves and ST depression.', 'The principal cells do the opposite and secrete potassium, under the control of aldosterone.'] },
  'AMB200-160': { c: 'Prerenal kidney injury from too much diuresis',
    w: 'A BUN to creatinine ratio above 20, concentrated urine and urine sodium below 20 mean the tubules are healthy and are holding on to salt. The kidneys are short of fluid because of strong diuretic treatment.',
    hy: ['Prerenal: fractional excretion of sodium below 1%, urine concentration above 500 and BUN to creatinine ratio above 20.', 'Acute tubular necrosis: fractional excretion of sodium above 2%, urine concentration below 350 and muddy brown casts.', 'NSAIDs (which narrow the vessel into the glomerulus) and ACE inhibitors make prerenal problems worse.'] },
  'AMB200-161': { c: 'Glomerulonephritis after a strep infection',
    w: 'Swelling around the eyes, cola-colored urine, high blood pressure and red cell casts 2 to 3 weeks after strep throat are post-streptococcal glomerulonephritis. Immunofluorescence shows lumpy deposits of IgG, IgM and C3.',
    hy: ['Electron microscopy shows humps under the epithelium. C3 is low, and ASO or anti-DNase B antibodies are raised.', 'In children it usually gets better on its own.', 'IgA nephropathy is different: blood in the urine 1 to 2 days after an infection, with a normal C3.'] },
  'AMB200-162': { c: 'Diabetic kidney disease: Kimmelstiel–Wilson nodules',
    w: 'Heavy protein in the urine with round nodules of scar in the glomeruli, in a patient who has not seen a doctor for years, is diabetic kidney disease.',
    hy: ['First the kidney filters too much, then small amounts of albumin appear in the urine. Sugar sticks to the basement membrane and damages it.', 'The vessel leaving the glomerulus thickens. ACE inhibitors, ARBs and SGLT2 inhibitors slow the damage.', 'Amyloid looks different: apple-green under polarized light with Congo red stain.'] },
  'AMB200-163': { c: 'Struvite stones come from bacteria that make urease',
    w: 'Repeated urine infections with stones and coffin-lid shaped crystals are struvite (magnesium ammonium phosphate) stones. Bacteria make urease, which splits urea into ammonia and makes the urine alkaline.',
    hy: ['Bacteria: Proteus, Klebsiella and Staphylococcus saprophyticus. The stones can grow into large staghorn shapes.', 'Calcium oxalate stones are the most common. They are linked to Crohn disease and ethylene glycol poisoning.', 'Uric acid stones do not show on X-ray and form in acidic urine. Cystine stones form hexagonal crystals.'] },
  'AMB200-164': { c: 'Staphylococcus saprophyticus urinary infection',
    w: 'A simple bladder infection in a sexually active young woman, with a negative nitrite test and a coagulase-negative staph that resists novobiocin, is Staphylococcus saprophyticus.',
    hy: ['It is the second most common cause of urinary infection in young women, after E. coli.', 'Staphylococcus epidermidis is sensitive to novobiocin.', 'Gram-positive bacteria do not turn nitrate into nitrite, so the nitrite test is negative.'] },
  'AMB200-165': { c: 'Stress incontinence: a urethra that moves too much',
    w: 'Leaking urine when laughing or sneezing, in a woman who has had several children, is stress incontinence. The pelvic floor is weak, so the urethra drops when pressure rises in the belly.',
    hy: ['Treatment: pelvic floor exercises, a pessary or a sling under the urethra.', 'Urge incontinence is different: the bladder muscle contracts on its own, and it is treated with antimuscarinics or mirabegron.', 'Normal pressure hydrocephalus causes incontinence with a wide-based, shuffling walk and confusion. She walks normally.'] },
  'AMB200-166': { c: 'Thiazides act on the distal tubule and can cause gout',
    w: 'A thiazide blocks the sodium–chloride carrier in the distal convoluted tubule. It also raises uric acid, which can trigger gout. Gout shows needle-shaped crystals that are negatively birefringent.',
    hy: ['Thiazides raise blood glucose, lipids, uric acid and calcium.', 'Thiazides lower the calcium in the urine, so they help prevent calcium stones and osteoporosis.', 'Loop diuretics also raise uric acid, but they make the body lose calcium.'] },
});

// ── Pregnancy & reproductive system ─────────────────────────────────────────
add({
  'AMB200-167': { c: 'Carbamazepine causes neural tube defects',
    w: 'Carbamazepine and valproate interfere with folate and can cause neural tube defects in the baby, such as spina bifida and meningocele.',
    hy: ['Women taking seizure medicines should take high-dose folic acid before they become pregnant.', 'Other harmful drugs in pregnancy: lithium (Ebstein anomaly), tetracycline (stained teeth), DES (vaginal cancer), ACE inhibitors (kidney damage) and thalidomide (limb defects).', 'Neural tube defects are screened for with a raised AFP in the mother’s blood.'] },
  'AMB200-168': { c: 'Congenital toxoplasmosis',
    w: 'Inflammation of the retina, fluid on the brain and calcium spots scattered throughout the brain are congenital toxoplasmosis.',
    hy: ['Classic triad: chorioretinitis, hydrocephalus and calcium deposits in the brain.', 'CMV is different: the calcium spots sit around the ventricles, the head is small and hearing is lost.', 'The mother catches it from cat feces or undercooked meat. It is treated with spiramycin or pyrimethamine.'] },
  'AMB200-169': { c: 'Vitelline duct cyst',
    w: 'A cyst behind the navel lined by bowel lining is a leftover of the vitelline duct, which once joined the gut to the yolk sac. It can also cause the bowel to twist (volvulus).',
    hy: ['If the whole duct stays open, stool leaks from the navel. If only part remains, it forms a Meckel diverticulum.', 'Meckel rule of twos: 2% of people, 2 feet from the end of the small bowel, 2 inches long and 2 types of tissue.', 'Urine leaking from the navel is a leftover of the urachus instead.'] },
  'AMB200-170': { c: 'Milestones at 2 years',
    w: 'At 2 years a child should walk up and down stairs and use about 50 words, putting two words together. She is behind in both. Scribbling, using a spoon and playing next to other children are normal for her age.',
    hy: ['2 years: climbs stairs, uses two-word phrases and about 50 words, plays next to others and kicks a ball.', '3 years: rides a tricycle, copies a circle, uses three-word sentences and shares.', '4 years: hops, copies a cross, tells stories and plays with others.'] },
  'AMB200-171': { c: 'Polycystic ovary syndrome raises the risk of endometrial cancer',
    w: 'Obesity, few periods, acne and extra hair are polycystic ovary syndrome. Because she rarely ovulates, the lining of the uterus is exposed to estrogen without progesterone to balance it. This can lead to endometrial hyperplasia and cancer.',
    hy: ['LH is high compared with FSH, androgens are high and the body resists insulin.', 'Treatment: the pill or a progestin to protect the uterus, metformin, and letrozole or clomiphene for fertility.', 'Ultrasound shows many small cysts around the edge of the ovary, like a string of pearls.'] },
  'AMB200-172': { c: 'Perimenopause: FSH rises',
    w: 'As the number of follicles falls, the ovaries make less estrogen and inhibin. The pituitary is no longer held back, so FSH rises first, followed by LH.',
    hy: ['Menopause means no periods for 12 months. The average age is 51.', 'Effects: hot flushes, a thin dry vagina, bone loss and more heart disease.', 'If the ovaries fail before age 40, it is called primary ovarian insufficiency.'] },
  'AMB200-173': { c: 'Turner syndrome: bicuspid aortic valve',
    w: 'Short stature, a webbed neck, a low hairline, a broad chest and short fourth knuckles are Turner syndrome (45,X). A bicuspid aortic valve, which can cause aortic stenosis, and narrowing of the aorta are common.',
    hy: ['The ovaries are thin streaks, so periods never start and FSH and LH are high.', 'Other findings: a horseshoe kidney, swollen hands and feet at birth and a fluid-filled swelling in the neck.', 'Intelligence is usually normal.'] },
  'AMB200-174': { c: 'Aromatase deficiency',
    w: 'Both the mother and the baby show male features. The placenta could not turn androgens into estrogens, so the androgens reached them both. The child later has no breast development, grows tall and has weak bones and ovarian cysts.',
    hy: ['Aromatase turns androgens into estrogens.', 'Estrogen is needed to close the growth plates and build bone, so without it the child grows tall and has low bone density.', 'Congenital adrenal hyperplasia (21-hydroxylase deficiency) does not cause male features in the mother.'] },
  'AMB200-175': { c: 'Adenomyosis',
    w: 'Heavy, painful periods with an evenly enlarged, soft uterus in a woman who has had several children are adenomyosis. The lining glands of the uterus have grown into its muscle wall.',
    hy: ['Fibroids are different: they make the uterus enlarged, firm and lumpy.', 'Treatment: NSAIDs and hormones. Removing the uterus is the only cure.', 'Endometriosis is different: the lining tissue grows outside the uterus, causing painful sex, infertility and chocolate cysts.'] },
  'AMB200-176': { c: 'Pelvic inflammatory disease (chlamydia) leads to ectopic pregnancy',
    w: 'Pain when the cervix is moved, pus-like discharge and bacteria seen inside cells are chlamydial pelvic inflammatory disease. Scarring of the fallopian tubes raises the risk of ectopic pregnancy and infertility.',
    hy: ['Fitz-Hugh–Curtis syndrome: inflammation around the liver with string-like scar bands.', 'Treatment: ceftriaxone with doxycycline, and sometimes metronidazole.', 'Chlamydia lives only inside cells and cannot be seen on a Gram stain.'] },
  'AMB200-177': { c: 'Indirect inguinal hernia and communicating hydrocele',
    w: 'A scrotal swelling that lets light through, grows when the baby cries and can be pushed back means the channel from the abdomen to the scrotum (the processus vaginalis) never closed.',
    hy: ['An indirect hernia passes through the deep inguinal ring, to the side of the inferior epigastric vessels. It is the most common type in babies.', 'A direct hernia pushes through a weak spot in the abdominal wall (Hesselbach triangle), toward the middle. It is more common in older men.', 'A varicocele feels like a bag of worms. It is made of swollen veins and is usually on the left.'] },
});

// ── Respiratory system ──────────────────────────────────────────────────────
add({
  'AMB200-178': { c: 'Type II pneumocytes repair the air sacs',
    w: 'After the air sacs are damaged, for example by influenza, type II pneumocytes multiply and turn into new type I cells to replace the ones that were lost.',
    hy: ['Type II cells also make surfactant and act as the stem cells of the air sacs.', 'Club cells in the small airways release protective proteins and break down toxins.', 'A lecithin to sphingomyelin ratio above 2 in the amniotic fluid means the baby’s lungs are mature.'] },
  'AMB200-179': { c: 'Acute respiratory acidosis from an opioid overdose',
    w: 'The patient is breathing only 5 times a minute and has pinpoint pupils. Carbon dioxide builds up quickly, so the pH falls. Bicarbonate is still normal because the kidneys have not had time to respond.',
    hy: ['Bicarbonate rises by about 1 for every 10 rise in carbon dioxide in acute cases, and by about 3.5 in chronic cases.', 'Treatment: naloxone.', 'A raised bicarbonate would mean chronic respiratory acidosis, as in long-standing COPD.'] },
  'AMB200-180': { c: 'An asthma attack traps air in both lungs',
    w: 'During an asthma attack air gets trapped in the lungs. Both sides are overinflated and sound hollow when tapped, breath sounds are quiet and vibration through the chest wall is reduced.',
    hy: ['Pneumothorax also sounds hollow, but only on one side, and breath sounds are absent there.', 'Pneumonia (consolidation) sounds dull, with more vibration and harsh (bronchial) breath sounds.', 'Fluid around the lung (pleural effusion) sounds dull, with less vibration and quiet breath sounds.'] },
  'AMB200-181': { c: 'Smoking causes centriacinar emphysema',
    w: 'Emphysema in the upper lobes, centered on the small airways, with large air pockets (bullae), is caused by long-term smoking.',
    hy: ['Smoking damages the center of the air sac units in the upper lobes. Alpha-1 antitrypsin deficiency damages the whole unit in the lower lobes.', 'Bullae can burst and cause a pneumothorax.', 'Stopping smoking is the most effective treatment.'] },
  'AMB200-182': { c: 'Emphysema lowers the diffusing capacity (DLCO)',
    w: 'A heavy smoker has airflow obstruction (FEV1/FVC below 70%) and a much lower diffusing capacity. This is emphysema, because the walls of the air sacs, where gas passes into the blood, have been destroyed.',
    hy: ['Chronic bronchitis also causes obstruction, but the diffusing capacity is close to normal.', 'Asthma causes obstruction that reverses, with a normal or high diffusing capacity.', 'Pulmonary fibrosis is a restrictive disease: low diffusing capacity with a normal or high FEV1/FVC.'] },
  'AMB200-183': { c: 'Cystic fibrosis: the vas deferens is missing',
    w: 'Repeated lung infections, fatty stools, poor growth and nasal polyps are cystic fibrosis. Almost all men with cystic fibrosis are born without a vas deferens on both sides, so they are infertile.',
    hy: ['The most common mutation, delta F508, makes the CFTR protein fold wrongly so it stays inside the cell. The disease is autosomal recessive.', 'Diagnosis: sweat chloride above 60. The newborn screen shows a high immunoreactive trypsinogen.', 'Common infections are Pseudomonas and Staphylococcus aureus. CFTR modulators such as ivacaftor help some mutations.'] },
  'AMB200-184': { c: 'Sarcoidosis: more CD4 than CD8 cells in lung washings',
    w: 'Swollen lymph nodes on both sides of the chest, tender red shin nodules, eye inflammation and high calcium (causing constipation) in a young woman are sarcoidosis. Fluid washed from the lungs shows many more CD4 than CD8 T cells.',
    hy: ['Granulomas without central necrosis. ACE is high. The granulomas make active vitamin D, which raises calcium and lowers PTH.', 'Löfgren syndrome: tender shin nodules, swollen chest nodes and joint pain.', 'Treatment: corticosteroids.'] },
  'AMB200-185': { c: 'Amiodarone can scar the lungs',
    w: 'Worsening breathlessness, clubbed fingers and a honeycomb pattern at the lung bases in a patient on amiodarone is drug-induced pulmonary fibrosis. Too much collagen is laid down in the lung.',
    hy: ['Drugs that scar the lung: amiodarone, bleomycin, busulfan, methotrexate and nitrofurantoin.', 'Amiodarone can also affect the thyroid and liver, leave deposits in the cornea and turn the skin blue-gray.', 'Lung tests show a restrictive pattern with a low diffusing capacity.'] },
  'AMB200-186': { c: 'Pulmonary embolism in a woman taking raloxifene',
    w: 'Chest pain on breathing, shortness of breath, low oxygen and respiratory alkalosis point to a pulmonary embolism. Raloxifene raises the risk of clots, so look for a clot in the leg veins too.',
    hy: ['Three things cause clots (Virchow triad): slow blood flow, damage to the vessel wall and blood that clots too easily.', 'Use the Wells score: if risk is low, check a D-dimer, and if risk is high, do a CT of the lung arteries.', 'Raloxifene, tamoxifen and the birth control pill all raise the risk of clots.'] },
  'AMB200-187': { c: 'Omalizumab: an antibody against IgE',
    w: 'Omalizumab binds free IgE in the blood, so IgE cannot attach to its receptors on mast cells and basophils. Over time these cells also show fewer IgE receptors, so allergic reactions are weaker.',
    hy: ['It is used for severe allergic asthma with high IgE that is not controlled by an inhaled steroid and a long-acting bronchodilator.', 'Other biologic drugs: mepolizumab and benralizumab block IL-5, and dupilumab blocks the IL-4 receptor.', 'Montelukast blocks leukotriene receptors, and zileuton blocks 5-lipoxygenase.'] },
});

// ── Biostatistics, epidemiology & social sciences ───────────────────────────
add({
  'AMB200-188': { c: 'Relative risk in a cohort study',
    w: 'A cohort study starts with exposure and follows people forward to see who gets the disease, so it measures relative risk. Divide the risk in the exposed group (30 out of 90) by the risk in the unexposed group (12 out of 45).',
    hy: ['Relative risk equals a/(a+b) divided by c/(c+d). Case-control studies use the odds ratio, ad/bc.', 'Attributable risk is the risk in the exposed group minus the risk in the unexposed group.', 'A relative risk above 1 means the exposure is linked to more of the outcome.'] },
  'AMB200-189': { c: 'A lower cutoff raises sensitivity and negative predictive value',
    w: 'Lowering the cutoff calls more people positive. More true cases are caught and fewer are missed, so sensitivity and negative predictive value rise. The cost is more false positives, so specificity and positive predictive value fall.',
    hy: ['Sensitivity is true positives divided by all people with the disease. A very sensitive test that is negative rules the disease out.', 'Specificity is true negatives divided by all people without the disease. A very specific test that is positive rules the disease in.', 'How common the disease is changes the predictive values, but not sensitivity or specificity.'] },
  'AMB200-190': { c: 'Reliability (precision) versus validity (accuracy)',
    w: 'Different examiners agreeing when they test the same patient is about reproducibility. This is precision, also called reliability.',
    hy: ['Random error lowers precision. Better precision makes confidence intervals narrower.', 'Accuracy (validity) is how close a result is to the truth. Systematic error lowers accuracy.', 'Agreement between examiners is measured with the kappa statistic.'] },
  'AMB200-191': { c: 'Case-control study',
    w: 'Starting with people who have the disease and people who do not, then looking back to see who was exposed, is a case-control study.',
    hy: ['It measures the odds ratio and works well for rare diseases.', 'It is prone to recall bias, because people with the disease may remember exposures differently.', 'A cohort study starts with exposure. A cross-sectional study looks at one point in time and measures prevalence.'] },
  'AMB200-192': { c: 'Confidence intervals and significance',
    w: 'The 95% confidence interval for study A includes 1.0, so the result is not significant (p above 0.05). The interval for study B does not include 1.0, so it is significant (p below 0.05). Study A therefore has the larger p-value.',
    hy: ['For a ratio, an interval that includes 1 means no significant difference. For a difference between groups, an interval that includes 0 means the same.', 'A narrower interval comes from a larger sample and means a more precise result.', 'A 95% confidence interval is the mean plus or minus 1.96 times the standard error.'] },
  'AMB200-193': { c: 'Statistical power equals 1 minus beta',
    w: 'Power rises when the chance of missing a real effect (type II error, beta) falls. In practice this means a bigger sample, a bigger effect or less variation in the data.',
    hy: ['A type I error (alpha) is a false positive. A type II error (beta) is a false negative.', 'Raising alpha would also raise power, but they want to keep alpha at 0.05.', 'Small pilot studies often do not have enough power to show a difference.'] },
  'AMB200-194': { c: 'Confounding, revealed by splitting the data into groups',
    w: 'Unemployment seemed linked to suicide overall. When the data were split by psychiatric history, the link disappeared in each group. Psychiatric history was therefore a confounder.',
    hy: ['A confounder is linked to both the exposure and the outcome. The link disappears once you split the data by it.', 'Effect modification is different: the link is still there, but it differs between groups.', 'Ways to control confounding: randomization, matching, restriction, stratification and multivariable analysis.'] },
  'AMB200-195': { c: 'Bladder cancer: smoking is the main cause',
    w: 'Painless blood in the urine with a bladder mass, and here bone metastases, is urothelial carcinoma. Its strongest risk factor is cigarette smoking.',
    hy: ['Other risks: aniline dyes, aromatic amines, cyclophosphamide and phenacetin.', 'Schistosoma haematobium infection causes squamous cell cancer of the bladder instead.', 'Painless blood in the urine in an older adult should be treated as bladder cancer until proven otherwise.'] },
  'AMB200-196': { c: 'A wide-based population pyramid: childhood immunizations',
    w: 'A pyramid with a wide base means many births and many early deaths. Child health measures such as immunizations lower early deaths and help the population move toward fewer births and longer lives.',
    hy: ['An expansive pyramid is typical of developing countries. A narrow-based pyramid means few births and an aging population.', 'A stationary pyramid means births and deaths are steady.', 'An aging population needs more care for long-term illness.'] },
  'AMB200-197': { c: 'Answer a parent’s worries with information',
    w: 'The best first step is to recognize the mother’s fear and ask if you can share accurate information. A short course of strong pain relief carries a low risk of addiction.',
    hy: ['Explore the worry and educate before considering going against the parent’s decision.', 'Treating without consent is only allowed in an emergency, when waiting would threaten life or limb.', 'Leaving sickle cell pain untreated leads to worse outcomes.'] },
  'AMB200-198': { c: 'Confidentiality: do not share without consent',
    w: 'The patient is able to make his own decisions and has said he does not want his family told. The doctor must not share the information and should encourage the daughter to talk to her father.',
    hy: ['Exceptions to confidentiality: danger to others, reportable diseases, abuse and court orders.', 'Never confirm or deny a diagnosis to relatives without the patient’s permission.', 'Offer to arrange a family meeting if the patient agrees.'] },
  'AMB200-199': { c: 'Use a professional medical interpreter',
    w: 'If no interpreter is available on site, use a professional medical interpreter by phone or video. Do not use family members, students or translation software.',
    hy: ['Family members may leave things out and break confidentiality.', 'Doctors with limited skill in the language should not interpret for themselves.', 'Speak to the patient, not to the interpreter.'] },
  'AMB200-200': { c: 'Abusive head trauma: subdural hematoma',
    w: 'An infant with drowsiness, a bulging soft spot and widespread bleeding in the retinas of both eyes, after a fall that does not explain it, has been shaken. Shaking tears the bridging veins and causes a subdural bleed.',
    hy: ['Torn bridging veins cause a crescent-shaped subdural bleed.', 'Look for fractures of the back of the ribs, small corner fractures at the ends of long bones and bruises in unusual places.', 'Suspected abuse must be reported.'] },
});

module.exports = HY;
